+
+.shell-layout__header {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: start;
+  justify-content: space-between;
+  gap: var(--shell-gap);
+  padding: clamp(1rem, 2vw, 1.5rem);
+}
+
+.shell-layout__headline {
