+    linear-gradient(180deg, rgba(255, 255, 255, 0.55), rgba(244, 241, 234, 0.96));
+}
+
+.shell-layout__header,
+.shell-section {
+  background: var(--shell-surface);
+  border: 1px solid var(--shell-border);
+  border-radius: var(--shell-radius);
+  box-shadow: var(--shell-shadow);
+  backdrop-filter: blur(16px);
+}
+
+.shell-layout__header {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: start;
+  justify-content: space-between;
+  gap: var(--shell-gap);
+  padding: clamp(1rem, 2vw, 1.5rem);
+}
+
+.shell-layout__headline {
+  display: grid;
+  gap: 0.35rem;
+  min-width: min(100%, 24rem);
+}
+
+.shell-layout__eyebrow {
+  margin: 0;
+  color: var(--shell-accent);
+  font-size: 0.78rem;
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+}
+
+.shell-layout__headline h1,
+.shell-section__header h2,
+.shell-section__header h3,
+.shell-section__header h4,
+.shell-section__header h5,
+.shell-section__header h6 {
+  margin: 0;
+  line-height: 1.08;
+}
+
+.shell-layout__headline h1 {
+  font-size: clamp(1.75rem, 3vw, 2.75rem);
+}
+
+.shell-layout__description,
+.shell-section__header p {
+  margin: 0;
+  color: var(--shell-muted);
+  max-width: 65ch;
+}
+
+.shell-layout__body {
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) minmax(18rem, 24rem);
+  gap: var(--shell-gap);
+  margin-top: var(--shell-gap);
+}
+
+.shell-layout__main,
+.shell-layout__aside,
+.shell-section__body {
+  display: grid;
+  gap: 1rem;
+}
+
+.shell-layout__main,
+.shell-layout__aside {
+  min-width: 0;
+}
+
+.shell-layout__main {
+  padding: clamp(1rem, 2vw, 1.5rem);
+  background: var(--shell-surface-strong);
+  border: 1px solid var(--shell-border);
+  border-radius: var(--shell-radius);
+}
+
