+  margin-top: var(--shell-gap);
+  padding-top: 1rem;
+  color: var(--shell-muted);
+}
+
+.shell-toolbar {
+  display: flex;
+  flex-wrap: wrap;
+  justify-content: flex-end;
+  gap: 0.75rem;
+}
+
