+  align-items: center;
+  justify-content: center;
+  min-height: 2.5rem;
+  padding: 0.55rem 0.95rem;
+  border-radius: 999px;
+  border: 1px solid rgba(24, 78, 119, 0.25);
+  background: linear-gradient(180deg, #ffffff, #edf4fb);
+  color: var(--shell-accent-strong);
+  font: inherit;
+  font-weight: 600;
+  text-decoration: none;
+  cursor: pointer;
+}
+
+.shell-action:hover,
+.shell-action:focus-visible {
+  border-color: rgba(24, 78, 119, 0.45);
+  box-shadow: 0 0 0 3px rgba(24, 78, 119, 0.14);
+  outline: none;
+}
+
+.shell-section {
+  padding: clamp(1rem, 2vw, 1.25rem);
+}
+
+.shell-section__header {
+  display: grid;
+  gap: 0.35rem;
+  margin-bottom: 1rem;
+}
+
+.shell-section__header h2,
+.shell-section__header h3,
+.shell-section__header h4,
+.shell-section__header h5,
+.shell-section__header h6 {
+  font-size: clamp(1.1rem, 1.9vw, 1.45rem);
+}
+
+.shell-section__body {
+  min-width: 0;
+}
+
+@media (max-width: 900px) {
+  .shell-layout__body {
+    grid-template-columns: minmax(0, 1fr);
+  }
+}
