@@ -0,0 +1,143 @@
+const listenersByNamespace = new Map();
+let storageEventsBound = false;
+
+function getWindowObject() {
+  if (typeof window !== "undefined" && window) {
+    return window;
+  }
+  return globalThis.window ?? null;
+}
+
+function getStorage() {
+  const win = getWindowObject();
+  return win?.localStorage ?? globalThis.localStorage ?? null;
+}
+
+function assertNamespace(namespace) {
+  if (typeof namespace !== "string" || namespace.length === 0) {
+    throw new TypeError("namespace must be a non-empty string");
+  }
+}
+
+function parseStoredValue(namespace, rawValue) {
+  if (rawValue === null) {
+    return null;
+  }
+
+  try {
+    return JSON.parse(rawValue);
+  } catch {
+    return null;
+  }
+}
+
+function notifyNamespace(namespace, value) {
+  const listeners = listenersByNamespace.get(namespace);
+  if (!listeners || listeners.size === 0) {
+    return;
+  }
+
+  for (const listener of listeners) {
+    listener(value);
+  }
+}
+
+function handleStorageEvent(event) {
+  if (!event || typeof event.key !== "string") {
+    return;
+  }
+
+  const namespace = event.key;
+  if (!listenersByNamespace.has(namespace)) {
+    return;
+  }
+
+  notifyNamespace(namespace, readNamespace(namespace));
+}
+
+function ensureStorageEvents() {
+  if (storageEventsBound) {
+    return;
+  }
+
+  const win = getWindowObject();
+  if (!win || typeof win.addEventListener !== "function") {
+    return;
+  }
+
+  win.addEventListener("storage", handleStorageEvent);
+  storageEventsBound = true;
+}
+
+function maybeRemoveStorageEvents() {
+  if (listenersByNamespace.size !== 0 || !storageEventsBound) {
+    return;
+  }
+
+  const win = getWindowObject();
+  if (!win || typeof win.removeEventListener !== "function") {
+    return;
+  }
+
+  win.removeEventListener("storage", handleStorageEvent);
+  storageEventsBound = false;
+}
+
+export function readNamespace(namespace) {
+  assertNamespace(namespace);
+
+  const storage = getStorage();
+  if (!storage) {
+    return null;
+  }
+
+  return parseStoredValue(namespace, storage.getItem(namespace));
+}
+
+export function writeNamespace(namespace, value) {
+  assertNamespace(namespace);
+
+  const storage = getStorage();
+  if (!storage) {
+    throw new Error("window.localStorage is not available");
+  }
+
+  const serialized = JSON.stringify(value);
+  if (typeof serialized !== "string") {
+    throw new TypeError("value must be JSON serializable");
+  }
+
+  storage.setItem(namespace, serialized);
+  notifyNamespace(namespace, value);
+  return value;
+}
+
+export function subscribe(namespace, listener) {
+  assertNamespace(namespace);
+
+  if (typeof listener !== "function") {
+    throw new TypeError("listener must be a function");
+  }
+
+  let listeners = listenersByNamespace.get(namespace);
+  if (!listeners) {
+    listeners = new Set();
+    listenersByNamespace.set(namespace, listeners);
+  }
+
+  listeners.add(listener);
+  ensureStorageEvents();
+
+  return () => {
+    const currentListeners = listenersByNamespace.get(namespace);
+    if (!currentListeners) {
+      return;
+    }
+
+    currentListeners.delete(listener);
+    if (currentListeners.size === 0) {
+      listenersByNamespace.delete(namespace);
+      maybeRemoveStorageEvents();
+    }
+  };
+}
diff --git a/public/shell/storage.test.mjs b/public/shell/storage.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..26b9fc05622d467e7c86a28090f6715fe300d167
--- /dev/null
+++ b/public/shell/storage.test.mjs
@@ -0,0 +1,107 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+const moduleUrl = new URL("./storage.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+    clear() {
+      store.clear();
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+let cleanup = () => {};
+
+async function loadStorageModule() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${moduleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("writeNamespace persists JSON under the exact namespace key", async () => {
+  const { readNamespace, writeNamespace } = await loadStorageModule();
+  const namespace = "shell:nav";
+  const value = { active: "trips", count: 3 };
+
+  const returned = writeNamespace(namespace, value);
+
+  assert.deepEqual(returned, value);
+  assert.equal(globalThis.localStorage.getItem(namespace), JSON.stringify(value));
+  assert.deepEqual(readNamespace(namespace), value);
+});
+
+test("subscribe receives same-tab writes and storage events", async () => {
+  const { subscribe, writeNamespace } = await loadStorageModule();
+  const namespace = "shell:state";
+  const observed = [];
+
+  const unsubscribe = subscribe(namespace, (value) => {
+    observed.push(value);
+  });
+
+  writeNamespace(namespace, { step: 1 });
+  assert.deepEqual(observed, [{ step: 1 }]);
+
+  globalThis.localStorage.setItem(namespace, JSON.stringify({ step: 2 }));
+  globalThis.window.dispatchStorageEvent(namespace);
+  assert.deepEqual(observed, [{ step: 1 }, { step: 2 }]);
+
+  unsubscribe();
+  writeNamespace(namespace, { step: 3 });
+  assert.deepEqual(observed, [{ step: 1 }, { step: 2 }]);
+});
+
+test("readNamespace returns null for malformed JSON instead of throwing", async () => {
+  const { readNamespace } = await loadStorageModule();
+  const namespace = "shell:broken";
+
+  globalThis.localStorage.setItem(namespace, "{not-json");
+
+  assert.equal(readNamespace(namespace), null);
+});
