index 0000000000000000000000000000000000000000..1bb069eaa4fa497e03bdaf4b06170fe032f3c345
--- /dev/null
+++ b/public/itinerary-stops/stops.mjs
@@ -0,0 +1,233 @@
+import { readNamespace, writeNamespace } from "../shell/storage.mjs";
+
+const STORAGE_NAMESPACE = "itinerary-stops";
+
+function getStoredStops() {
+  const stored = readNamespace(STORAGE_NAMESPACE);
+  if (!Array.isArray(stored)) {
+    return [];
+  }
+
+  return stored
+    .map(normalizeStoredStop)
+    .filter((stop) => stop !== null);
+}
+
+function normalizeText(value) {
+  if (typeof value === "string") {
+    return value;
+  }
+
+  if (value === null || value === undefined) {
+    return "";
+  }
+
+  return String(value);
+}
+
+function normalizeOrder(value, fallback) {
+  if (Number.isFinite(value)) {
+    return Math.trunc(value);
+  }
+
+  return fallback;
+}
+
+function normalizeStoredStop(stop) {
+  if (!stop || typeof stop !== "object") {
+    return null;
+  }
+
+  const id = normalizeText(stop.id);
+  if (!id) {
+    return null;
+  }
+
+  return {
+    id,
+    name: normalizeText(stop.name),
+    startDate: normalizeText(stop.startDate),
+    endDate: normalizeText(stop.endDate),
+    description: normalizeText(stop.description),
+    order: normalizeOrder(stop.order, 0),
+  };
+}
+
+function normalizeStop(input, fallbackOrder = 0) {
+  const stop = normalizeStoredStop(input);
+  if (!stop) {
+    return {
+      id: "",
+      name: "",
+      startDate: "",
+      endDate: "",
+      description: "",
+      order: fallbackOrder,
+    };
+  }
+
+  return {
+    id: stop.id,
+    name: stop.name,
+    startDate: stop.startDate,
+    endDate: stop.endDate,
+    description: stop.description,
+    order: normalizeOrder(stop.order, fallbackOrder),
+  };
+}
+
+function persistStops(stops) {
+  return writeNamespace(
+    STORAGE_NAMESPACE,
+    stops.map((stop, index) => ({
+      id: stop.id,
+      name: stop.name,
+      startDate: stop.startDate,
+      endDate: stop.endDate,
+      description: stop.description,
+      order: index + 1,
+    })),
+  );
+}
+
+function nextStopId() {
+  const cryptoObject = globalThis.crypto;
+  if (cryptoObject && typeof cryptoObject.randomUUID === "function") {
+    return cryptoObject.randomUUID();
+  }
+
+  return `stop-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+function sortStops(stops) {
+  return [...stops].sort((left, right) => {
+    const orderDelta = left.order - right.order;
+    if (orderDelta !== 0) {
+      return orderDelta;
+    }
+
+    return left.id.localeCompare(right.id);
+  });
+}
+
+function findStopIndex(stops, id) {
+  return stops.findIndex((stop) => stop.id === id);
+}
+
+function coerceUpdateArgs(idOrPatch, maybePatch) {
+  if (idOrPatch && typeof idOrPatch === "object" && !Array.isArray(idOrPatch)) {
+    const { id, ...patch } = idOrPatch;
+    return { id: normalizeText(id), patch };
+  }
+
+  return {
+    id: normalizeText(idOrPatch),
+    patch: maybePatch && typeof maybePatch === "object" ? maybePatch : {},
+  };
+}
+
+export function listStops() {
+  return sortStops(getStoredStops());
+}
+
+export function createStop(input = {}) {
+  const stops = getStoredStops();
+  const stop = normalizeStop(input, stops.length + 1);
+
+  const created = {
+    id: nextStopId(),
+    name: stop.name,
+    startDate: stop.startDate,
+    endDate: stop.endDate,
+    description: stop.description,
+    order: stops.length + 1,
+  };
+
+  persistStops([...stops, created]);
+  return created;
+}
+
+export function updateStop(idOrPatch, maybePatch) {
+  const { id, patch } = coerceUpdateArgs(idOrPatch, maybePatch);
+  if (!id) {
+    throw new TypeError("stop id must be a non-empty string");
+  }
+
+  const stops = getStoredStops();
+  const index = findStopIndex(stops, id);
+  if (index === -1) {
+    throw new RangeError(`stop not found: ${id}`);
+  }
+
+  const current = stops[index];
+  const next = {
+    id: current.id,
+    name: normalizeText(patch.name ?? current.name),
+    startDate: normalizeText(patch.startDate ?? current.startDate),
+    endDate: normalizeText(patch.endDate ?? current.endDate),
+    description: normalizeText(patch.description ?? current.description),
+    order: current.order,
+  };
+
+  stops[index] = next;
+  persistStops(sortStops(stops));
+  return next;
+}
+
+export function removeStop(idOrStop) {
+  const id = normalizeText(
+    idOrStop && typeof idOrStop === "object" && !Array.isArray(idOrStop)
+      ? idOrStop.id
+      : idOrStop,
+  );
+
+  if (!id) {
+    throw new TypeError("stop id must be a non-empty string");
+  }
+
+  const stops = getStoredStops();
+  const index = findStopIndex(stops, id);
+  if (index === -1) {
+    throw new RangeError(`stop not found: ${id}`);
+  }
+
+  stops.splice(index, 1);
+  return persistStops(sortStops(stops));
+}
+
+export function reorderStops(order) {
+  const stops = getStoredStops();
+  if (!Array.isArray(order)) {
+    throw new TypeError("order must be an array");
+  }
+
+  const byId = new Map(stops.map((stop) => [stop.id, stop]));
+  const nextStops = [];
+  const seen = new Set();
+
+  for (const entry of order) {
+    const id =
+      typeof entry === "string"
+        ? entry
+        : entry && typeof entry === "object"
+          ? normalizeText(entry.id)
+          : "";
+
+    if (!id || seen.has(id) || !byId.has(id)) {
+      continue;
+    }
+
+    nextStops.push(byId.get(id));
+    seen.add(id);
+  }
+
+  for (const stop of sortStops(stops)) {
+    if (!seen.has(stop.id)) {
+      nextStops.push(stop);
+      seen.add(stop.id);
+    }
+  }
+
+  return persistStops(nextStops);
+}
+
