index 0000000000000000000000000000000000000000..ab2cac8952df33ffa51bca8f2650e592b1dd525e
--- /dev/null
+++ b/public/itinerary-stops/stops.test.mjs
@@ -0,0 +1,190 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+const moduleUrl = new URL("./stops.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+  };
+}
+
+let cleanup = () => {};
+
+async function loadStopsModule() {
+  const storage = createFakeStorage();
+  globalThis.localStorage = storage;
+  globalThis.window = createFakeWindow(storage);
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${moduleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("createStop, updateStop, removeStop and reorderStops persist the itinerary stops contract", async () => {
+  const { createStop, listStops, removeStop, reorderStops, updateStop } = await loadStopsModule();
+
+  const first = createStop({
+    name: "Madrid",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Inicio del viaje",
+  });
+  const second = createStop({
+    name: "Toledo",
+    startDate: "2026-09-03",
+    endDate: "2026-09-04",
+    description: "Noche corta",
+  });
+
+  assert.equal(first.order, 1);
+  assert.equal(second.order, 2);
+  assert.match(first.id, /^stop-/);
+  assert.deepEqual(listStops(), [first, second]);
+
+  const updated = updateStop(first.id, {
+    name: "Madrid centro",
+    description: "Primer tramo del itinerario integrado",
+  });
+  assert.deepEqual(updated, {
