+import assert from "node:assert/strict";
+import test from "node:test";
+
+const moduleUrl = new URL("./stops.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+  };
+}
+
+let cleanup = () => {};
+
+async function loadStopsModule() {
+  const storage = createFakeStorage();
+  globalThis.localStorage = storage;
+  globalThis.window = createFakeWindow(storage);
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${moduleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("createStop, updateStop, removeStop and reorderStops persist the itinerary stops contract", async () => {
+  const { createStop, listStops, removeStop, reorderStops, updateStop } = await loadStopsModule();
+
+  const first = createStop({
+    name: "Madrid",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Inicio del viaje",
+  });
+  const second = createStop({
+    name: "Toledo",
+    startDate: "2026-09-03",
+    endDate: "2026-09-04",
+    description: "Noche corta",
+  });
+
+  assert.equal(first.order, 1);
+  assert.equal(second.order, 2);
+  assert.match(first.id, /^stop-/);
+  assert.deepEqual(listStops(), [first, second]);
+
+  const updated = updateStop(first.id, {
+    name: "Madrid centro",
+    description: "Primer tramo del itinerario integrado",
+  });
+  assert.deepEqual(updated, {
+    ...first,
+    name: "Madrid centro",
+    description: "Primer tramo del itinerario integrado",
+  });
+
+  assert.deepEqual(listStops(), [
+    updated,
+    second,
+  ]);
+
+  const reordered = reorderStops([second.id, first.id]);
+  assert.deepEqual(reordered, [
+    {
+      ...second,
+      order: 1,
+    },
+    {
+      ...updated,
+      order: 2,
+    },
+  ]);
+
+  assert.deepEqual(listStops(), reordered);
+
+  const remaining = removeStop(first.id);
+  assert.deepEqual(remaining, [
+    {
+      ...second,
+      order: 1,
+    },
+  ]);
+
+  assert.deepEqual(listStops(), remaining);
+  assert.deepEqual(globalThis.localStorage.getItem("itinerary-stops"), JSON.stringify(remaining));
+});
+
+test("reorderStops preserves missing stops and listStops ignores malformed storage entries", async () => {
+  const { listStops, reorderStops } = await loadStopsModule();
+
+  globalThis.localStorage.setItem(
+    "itinerary-stops",
+    JSON.stringify([
+      {
+        id: "a",
+        name: "A",
+        startDate: "2026-01-01",
+        endDate: "2026-01-02",
+        description: "",
+        order: 2,
+      },
+      {
+        id: "",
+        name: "skip",
+        startDate: "",
+        endDate: "",
+        description: "",
+        order: 1,
+      },
+      {
+        id: "b",
+        name: "B",
+        startDate: "2026-01-03",
+        endDate: "2026-01-04",
+        description: "keep",
+        order: 1,
+      },
+    ]),
+  );
+
+  assert.deepEqual(listStops(), [
+    {
+      id: "b",
+      name: "B",
+      startDate: "2026-01-03",
+      endDate: "2026-01-04",
+      description: "keep",
+      order: 1,
+    },
+    {
+      id: "a",
+      name: "A",
+      startDate: "2026-01-01",
+      endDate: "2026-01-02",
+      description: "",
+      order: 2,
+    },
+  ]);
+
+  const reordered = reorderStops(["a"]);
+  assert.deepEqual(reordered, [
+    {
+      id: "a",
+      name: "A",
+      startDate: "2026-01-01",
+      endDate: "2026-01-02",
+      description: "",
+      order: 1,
+    },
+    {
+      id: "b",
+      name: "B",
