import { readNamespace, subscribe, writeNamespace } from "../shell/storage.mjs";

export const budgetNamespace = "organization-budget";

const visualStates = Object.freeze({
  safe: "safe",
  warning: "warning",
  critical: "critical",
});

function getDocument() {
  const doc = globalThis.document;
  if (!doc || typeof doc.createElement !== "function") {
    throw new Error("document is required to render organization budget");
  }
  return doc;
}

function coerceText(value, fallback = "") {
  if (typeof value === "string") {
    return value.trim() || fallback;
  }
  if (typeof value === "number" && Number.isFinite(value)) {
    return String(value);
  }
  return fallback;
}

function coerceAmount(value, fallback = 0) {
  const amount = typeof value === "number" ? value : Number(value);
  return Number.isFinite(amount) ? amount : fallback;
}

function normalizeCategoryItem(item) {
  if (!item || typeof item !== "object") {
    return null;
  }

  const category = coerceText(item.category);
  const amount = coerceAmount(item.amount);

  if (!category) {
    return null;
  }

  return {
    category,
    amount,
  };
}

function normalizeExpenses(expenses) {
  if (!Array.isArray(expenses)) {
    return [];
  }

  return expenses.map(normalizeCategoryItem).filter(Boolean);
}

function normalizeOrganization(organization) {
  const source = organization && typeof organization === "object" ? organization : {};
  const name = coerceText(source.name, "Organizacion integrada");

  return {
    name,
    integrated: true,
  };
}

export function createBudgetState(input = {}) {
  const source = input && typeof input === "object" ? input : {};
  const totalBudget = coerceAmount(source.totalBudget);
  const expenses = normalizeExpenses(source.expenses);
  const organization = normalizeOrganization(source.organization);

  return {
    organization,
    totalBudget,
    expenses,
  };
}

export function calculateBudgetSummary(state) {
  const budgetState = createBudgetState(state);
  const spent = budgetState.expenses.reduce((sum, item) => sum + item.amount, 0);
  const available = budgetState.totalBudget - spent;
  const categoryTotals = new Map();

  for (const item of budgetState.expenses) {
    categoryTotals.set(item.category, (categoryTotals.get(item.category) ?? 0) + item.amount);
  }

  const spentRatio = budgetState.totalBudget > 0 ? spent / budgetState.totalBudget : spent > 0 ? 1 : 0;
  const availableState = available < 0 ? visualStates.critical : available <= budgetState.totalBudget * 0.2 ? visualStates.warning : visualStates.safe;
  const spentState = spentRatio >= 1 ? visualStates.critical : spentRatio >= 0.8 ? visualStates.warning : visualStates.safe;

  return {
    organization: budgetState.organization,
    totalBudget: budgetState.totalBudget,
    spent,
    available,
    spentState,
    availableState,
    categories: Array.from(categoryTotals, ([category, amount]) => ({ category, amount })),
  };
}

export function addExpense(state, expense) {
  const budgetState = createBudgetState(state);
  const normalizedExpense = normalizeCategoryItem(expense);

  if (!normalizedExpense) {
    return budgetState;
  }

  return {
    ...budgetState,
    expenses: [...budgetState.expenses, normalizedExpense],
  };
}

export function saveBudgetState(state) {
  return writeNamespace(budgetNamespace, createBudgetState(state));
}

export function loadBudgetState() {
  return createBudgetState(readNamespace(budgetNamespace) ?? {});
}

export function subscribeBudget(listener) {
  if (typeof listener !== "function") {
    throw new TypeError("listener must be a function");
  }

  return subscribe(budgetNamespace, () => {
    listener(loadBudgetState());
  });
}

function appendText(doc, target, value) {
  if (value === null || value === undefined || value === "") {
    return;
  }
  target.appendChild(doc.createTextNode(String(value)));
}

function createMetricCard(doc, label, amount, stateName) {
  const card = doc.createElement("article");
  card.className = `budget-metric budget-metric--${stateName}`;

  const title = doc.createElement("p");
  title.className = "budget-metric__label";
  title.textContent = label;
  card.appendChild(title);

  const value = doc.createElement("strong");
  value.className = "budget-metric__value";
  value.textContent = amount.toLocaleString("es-AR", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  });
  card.appendChild(value);

  return card;
}

function createCategoryRow(doc, category, amount) {
  const row = doc.createElement("li");
  row.className = "budget-category";

  const name = doc.createElement("span");
  name.className = "budget-category__name";
  name.textContent = category;
  row.appendChild(name);

  const value = doc.createElement("span");
  value.className = "budget-category__amount";
  value.textContent = amount.toLocaleString("es-AR", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  });
  row.appendChild(value);

  return row;
}

export function renderOrganizationBudget(state) {
  const doc = getDocument();
  const summary = calculateBudgetSummary(state);

  const root = doc.createElement("section");
  root.className = "organization-budget";
  root.setAttribute("aria-label", "Presupuesto de organizacion");

  const header = doc.createElement("header");
  header.className = "organization-budget__header";

  const eyebrow = doc.createElement("p");
  eyebrow.className = "organization-budget__eyebrow";
  eyebrow.textContent = "Presupuesto";
  header.appendChild(eyebrow);

  const heading = doc.createElement("h1");
  heading.className = "organization-budget__title";
  heading.textContent = summary.organization.name;
  header.appendChild(heading);

  const integration = doc.createElement("p");
  integration.className = "organization-budget__integration";
  integration.textContent = summary.organization.integrated
    ? "Creacion de organizacion integrada activa"
    : "Organizacion no integrada";
  header.appendChild(integration);

  root.appendChild(header);

  const metrics = doc.createElement("div");
  metrics.className = "organization-budget__metrics";
  metrics.appendChild(createMetricCard(doc, "Total presupuestado", summary.totalBudget, "safe"));
  metrics.appendChild(createMetricCard(doc, "Gastado", summary.spent, summary.spentState));
  metrics.appendChild(createMetricCard(doc, "Disponible", summary.available, summary.availableState));
  root.appendChild(metrics);

  const detail = doc.createElement("section");
  detail.className = "organization-budget__detail";

  const detailHeading = doc.createElement("h2");
  detailHeading.textContent = "Gastos por categoria";
  detail.appendChild(detailHeading);

  const list = doc.createElement("ul");
  list.className = "organization-budget__categories";

  if (summary.categories.length === 0) {
    const empty = doc.createElement("li");
    empty.className = "budget-category budget-category--empty";
    empty.textContent = "Sin gastos cargados";
    list.appendChild(empty);
  } else {
    for (const item of summary.categories) {
      list.appendChild(createCategoryRow(doc, item.category, item.amount));
    }
  }

  detail.appendChild(list);
  root.appendChild(detail);

  const status = doc.createElement("p");
  status.className = `organization-budget__status organization-budget__status--${summary.availableState}`;
  appendText(doc, status, summary.available < 0 ? "El presupuesto esta excedido" : "El presupuesto esta disponible");
  root.appendChild(status);

  return root;
}

