+import { readNamespace, subscribe, writeNamespace } from "../shell/storage.mjs";
+
+export const NOTES_NAMESPACE = "memories-notes";
+
+let idCounter = 0;
+
+function nextId(prefix) {
+  idCounter += 1;
+  return `${prefix}-${idCounter}`;
+}
+
+function nowIso() {
+  return new Date().toISOString();
+}
+
+function asNonEmptyString(value, fieldName) {
+  if (typeof value !== "string") {
+    throw new TypeError(`${fieldName} must be a non-empty string`);
+  }
+
+  const trimmed = value.trim();
+  if (trimmed.length === 0) {
+    throw new TypeError(`${fieldName} must be a non-empty string`);
+  }
+
+  return trimmed;
+}
+
+function asOptionalAssociation(value, fieldName) {
+  if (value === undefined || value === null) {
+    return null;
+  }
+
+  return asNonEmptyString(value, fieldName);
+}
+
+function isPlainObject(value) {
+  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
+}
+
+function normalizeIntegratedMemory(note, input) {
+  if (input === undefined || input === null) {
+    return null;
+  }
+
+  if (!isPlainObject(input)) {
+    throw new TypeError("memory must be an object");
+  }
+
+  const createdAt = asOptionalAssociation(input.createdAt, "memory.createdAt") ?? note.createdAt;
+  const updatedAt = asOptionalAssociation(input.updatedAt, "memory.updatedAt") ?? createdAt;
+
+  return {
+    ...input,
+    id: asOptionalAssociation(input.id, "memory.id") ?? nextId("memory"),
+    noteId: asOptionalAssociation(input.noteId, "memory.noteId") ?? note.id,
+    dayId: asOptionalAssociation(input.dayId, "memory.dayId") ?? note.dayId,
+    stopId: asOptionalAssociation(input.stopId, "memory.stopId") ?? note.stopId,
+    title: asOptionalAssociation(input.title, "memory.title") ?? note.text,
+    summary: asOptionalAssociation(input.summary, "memory.summary") ?? note.text,
+    source: asOptionalAssociation(input.source, "memory.source") ?? "note",
+    createdAt,
+    updatedAt,
+  };
+}
+
+function normalizeNoteShape(input) {
+  if (typeof input === "string") {
+    input = { text: input };
+  }
+
+  if (!isPlainObject(input)) {
+    throw new TypeError("note must be an object");
+  }
+
+  const text = asNonEmptyString(input.text, "text");
+  const dayId = asOptionalAssociation(input.dayId, "dayId");
+  const stopId = asOptionalAssociation(input.stopId, "stopId");
+
+  if (!dayId && !stopId) {
+    throw new TypeError("note must be associated with a day or a stop");
+  }
+
+  const createdAt = asOptionalAssociation(input.createdAt, "createdAt") ?? nowIso();
+  const updatedAt = asOptionalAssociation(input.updatedAt, "updatedAt") ?? createdAt;
+
+  const note = {
+    ...input,
+    id: asOptionalAssociation(input.id, "id") ?? nextId("note"),
+    text,
+    dayId,
+    stopId,
+    createdAt,
+    updatedAt,
+  };
+
+  const memoryInput = input.memory ?? input.integratedMemory ?? null;
+  note.memory = normalizeIntegratedMemory(note, memoryInput);
+
+  delete note.integratedMemory;
+
+  return note;
+}
+
+function normalizeStoredNotes(value) {
+  if (!Array.isArray(value)) {
+    return [];
+  }
+
+  return value.map((item) => normalizeNoteShape(item));
+}
+
+export function readNotes() {
+  const stored = readNamespace(NOTES_NAMESPACE);
+  return normalizeStoredNotes(stored);
+}
+
+export function writeNotes(notes) {
+  if (!Array.isArray(notes)) {
+    throw new TypeError("notes must be an array");
+  }
+
+  const normalized = notes.map((note) => normalizeNoteShape(note));
+  writeNamespace(NOTES_NAMESPACE, normalized);
+  return normalized;
+}
+
+export function createIntegratedMemory(note, memory = {}) {
+  const normalizedNote = normalizeNoteShape(note);
+  return normalizeIntegratedMemory(normalizedNote, memory);
+}
+
+export function createNote(note) {
+  return normalizeNoteShape(note);
+}
+
+export function addNote(note) {
+  const normalizedNote = normalizeNoteShape(note);
+  const notes = readNotes();
+  const nextNotes = [...notes, normalizedNote];
+  writeNamespace(NOTES_NAMESPACE, nextNotes);
+  return normalizedNote;
+}
+
+export function subscribeNotes(listener) {
+  if (typeof listener !== "function") {
+    throw new TypeError("listener must be a function");
+  }
+
+  return subscribe(NOTES_NAMESPACE, () => {
+    listener(readNotes());
+  });
+}
+
