+import assert from "node:assert/strict";
+import test from "node:test";
+
+const moduleUrl = new URL("./notes.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+    clear() {
+      store.clear();
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+let cleanup = () => {};
+
+async function loadNotesModule() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${moduleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("Notas guarda una nota asociada a un día con un recuerdo integrado", async () => {
+  const { addNote, readNotes } = await loadNotesModule();
+
+  const note = addNote({
+    text: "Reservar el desayuno temprano",
+    dayId: "day-1",
+    integratedMemory: {
+      title: "Desayuno en la terraza",
+      summary: "La familia empezó el día sin apuro.",
+    },
+  });
+
+  assert.equal(note.text, "Reservar el desayuno temprano");
+  assert.equal(note.dayId, "day-1");
+  assert.equal(note.stopId, null);
+  assert.ok(note.memory);
+  assert.equal(note.memory.title, "Desayuno en la terraza");
+  assert.equal(note.memory.summary, "La familia empezó el día sin apuro.");
+  assert.equal(note.memory.noteId, note.id);
+  assert.equal(note.memory.dayId, "day-1");
+
+  assert.deepEqual(readNotes(), [note]);
+});
+
+test("Notas guarda una nota asociada a una parada y conserva recuerdos integrados creados", async () => {
+  const { addNote, createIntegratedMemory, readNotes } = await loadNotesModule();
+
+  const draftMemory = createIntegratedMemory(
+    {
+      text: "Mirador al atardecer",
+      stopId: "stop-7",
+    },
+    {
+      title: "Vista al río",
+      tags: ["sunset", "family"],
+    },
+  );
+
+  const note = addNote({
+    text: "Mirador al atardecer",
+    stopId: "stop-7",
+    memory: draftMemory,
+  });
+
+  assert.equal(note.stopId, "stop-7");
+  assert.equal(note.dayId, null);
+  assert.equal(note.memory.id, draftMemory.id);
+  assert.equal(note.memory.title, "Vista al río");
+  assert.deepEqual(note.memory.tags, ["sunset", "family"]);
+
+  assert.equal(readNotes().length, 1);
+  assert.deepEqual(readNotes()[0], note);
+});
+
+test("subscribeNotes emits the current list for same-tab writes and storage events", async () => {
+  const { subscribeNotes, writeNotes } = await loadNotesModule();
+  const observed = [];
+
+  const unsubscribe = subscribeNotes((notes) => {
+    observed.push(notes);
+  });
+
+  writeNotes([
+    {
+      text: "Anotar una pausa",
+      dayId: "day-2",
+    },
+  ]);
+
+  assert.equal(observed.length, 1);
+  assert.equal(observed[0][0].text, "Anotar una pausa");
+
+  globalThis.localStorage.setItem(
+    "memories-notes",
+    JSON.stringify([
+      {
+        text: "Cambio desde otra pestaña",
+        stopId: "stop-3",
+      },
+    ]),
+  );
+  globalThis.window.dispatchStorageEvent("memories-notes");
+
+  assert.equal(observed.length, 2);
+  assert.equal(observed[1][0].stopId, "stop-3");
+
+  unsubscribe();
+  writeNotes([
+    {
+      text: "No debe notificarse",
+      dayId: "day-9",
+    },
+  ]);
+
+  assert.equal(observed.length, 2);
+});
