+import { readNamespace, subscribe, writeNamespace } from "../shell/storage.mjs";
+
+export const FAVORITES_NAMESPACE = "memories-favorites";
+
+const FAVORITE_TYPE_ALIASES = new Map([
+  ["lugar", "place"],
+  ["actividad", "activity"],
+]);
+
+let idCounter = 0;
+
+function nextId(prefix) {
+  idCounter += 1;
+  return `${prefix}-${idCounter}`;
+}
+
+function clone(value) {
+  return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
+}
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function ensureNonEmptyString(value, name) {
+  if (typeof value !== "string" || value.trim().length === 0) {
+    throw new TypeError(`${name} must be a non-empty string`);
+  }
+  return value.trim();
+}
+
+function normalizeType(value) {
+  const raw = ensureNonEmptyString(value, "favorite type").toLowerCase();
+  return FAVORITE_TYPE_ALIASES.get(raw) ?? raw;
+}
+
+function normalizeTimestamp(value, fallback = new Date().toISOString()) {
+  if (typeof value !== "string" || value.trim().length === 0) {
+    return fallback;
+  }
+
+  const parsed = Date.parse(value);
+  return Number.isNaN(parsed) ? fallback : new Date(parsed).toISOString();
+}
+
+function normalizeMemory(memory, favorite) {
+  const base = isRecord(memory) ? memory : {};
+  const createdAt = normalizeTimestamp(base.createdAt);
+  const id = typeof base.id === "string" && base.id.trim().length > 0
+    ? base.id.trim()
+    : nextId("memory");
+  const title = typeof base.title === "string" && base.title.trim().length > 0
+    ? base.title.trim()
+    : favorite.title;
+  const note = typeof base.note === "string" ? base.note : favorite.note ?? "";
+
+  return {
+    id,
+    title,
+    note,
+    createdAt,
+    source: "favorite",
+    favoriteId: favorite.id,
+    favoriteType: favorite.type,
+  };
+}
+
+function normalizeFavorite(favorite) {
+  if (!isRecord(favorite)) {
+    throw new TypeError("favorite must be an object");
+  }
+
+  const title = ensureNonEmptyString(favorite.title, "favorite title");
+  const type = normalizeType(favorite.type ?? favorite.kind ?? favorite.category ?? "place");
+  const createdAt = normalizeTimestamp(favorite.createdAt);
+  const updatedAt = normalizeTimestamp(favorite.updatedAt, createdAt);
+  const id = typeof favorite.id === "string" && favorite.id.trim().length > 0
+    ? favorite.id.trim()
+    : nextId("favorite");
+  const note = typeof favorite.note === "string" ? favorite.note : "";
+
+  const normalized = {
+    id,
+    type,
+    title,
+    note,
+    createdAt,
+    updatedAt,
+  };
+
+  const memory = normalizeMemory(favorite.memory, normalized);
+  normalized.memoryId = memory.id;
+  normalized.memory = memory;
+
+  return normalized;
+}
+
+function normalizeState(rawState) {
