+class FakeNode {
+  constructor(nodeType) {
+    this.nodeType = nodeType;
+    this.childNodes = [];
+    this.parentNode = null;
+    this._textContent = "";
+    this.eventListeners = new Map();
+    this.attributes = new Map();
+    this.className = "";
+    this.style = {};
