+  }
+
+  getAttribute(name) {
+    return this.attributes.has(name) ? this.attributes.get(name) : null;
+  }
+
+  set textContent(value) {
+    this._textContent = String(value);
+    this.childNodes = [];
+  }
+
+  get textContent() {
+    if (this.childNodes.length === 0) {
+      return this._textContent;
+    }
