+  if (normalizedFilter === packingStates.packed) {
+    return items.filter((item) => Boolean(item?.packed));
+  }
+
+  if (normalizedFilter === packingStates.pending) {
+    return items.filter((item) => !Boolean(item?.packed));
+  }
