+  return {
+    ...input,
+    id: asOptionalAssociation(input.id, "memory.id") ?? nextId("memory"),
+    noteId: asOptionalAssociation(input.noteId, "memory.noteId") ?? note.id,
+    dayId: asOptionalAssociation(input.dayId, "memory.dayId") ?? note.dayId,
+    stopId: asOptionalAssociation(input.stopId, "memory.stopId") ?? note.stopId,
+    title: asOptionalAssociation(input.title, "memory.title") ?? note.text,
+    summary: asOptionalAssociation(input.summary, "memory.summary") ?? note.text,
+    source: asOptionalAssociation(input.source, "memory.source") ?? "note",
+    createdAt,
+    updatedAt,
+  };
+}
+
+function normalizeNoteShape(input) {
+  if (typeof input === "string") {
