+import { readNamespace, subscribe, writeNamespace } from "../shell/storage.mjs";
+
+export const FAVORITES_NAMESPACE = "memories-favorites";
+
+const FAVORITE_TYPE_ALIASES = new Map([
+  ["lugar", "place"],
+  ["actividad", "activity"],
+]);
+
+let idCounter = 0;
+
+function nextId(prefix) {
+  idCounter += 1;
+  return `${prefix}-${idCounter}`;
+}
+
+function clone(value) {
+  return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
+}
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function ensureNonEmptyString(value, name) {
+  if (typeof value !== "string" || value.trim().length === 0) {
+    throw new TypeError(`${name} must be a non-empty string`);
+  }
+  return value.trim();
+}
+
+function normalizeType(value) {
+  const raw = ensureNonEmptyString(value, "favorite type").toLowerCase();
+  return FAVORITE_TYPE_ALIASES.get(raw) ?? raw;
+}
+
+function normalizeTimestamp(value, fallback = new Date().toISOString()) {
+  if (typeof value !== "string" || value.trim().length === 0) {
+    return fallback;
+  }
+
+  const parsed = Date.parse(value);
+  return Number.isNaN(parsed) ? fallback : new Date(parsed).toISOString();
+}
+
+function normalizeMemory(memory, favorite) {
+  const base = isRecord(memory) ? memory : {};
+  const createdAt = normalizeTimestamp(base.createdAt);
+  const id = typeof base.id === "string" && base.id.trim().length > 0
+    ? base.id.trim()
+    : nextId("memory");
+  const title = typeof base.title === "string" && base.title.trim().length > 0
+    ? base.title.trim()
+    : favorite.title;
+  const note = typeof base.note === "string" ? base.note : favorite.note ?? "";
+
+  return {
+    id,
+    title,
+    note,
+    createdAt,
+    source: "favorite",
+    favoriteId: favorite.id,
+    favoriteType: favorite.type,
+  };
+}
+
+function normalizeFavorite(favorite) {
+  if (!isRecord(favorite)) {
+    throw new TypeError("favorite must be an object");
+  }
+
+  const title = ensureNonEmptyString(favorite.title, "favorite title");
+  const type = normalizeType(favorite.type ?? favorite.kind ?? favorite.category ?? "place");
+  const createdAt = normalizeTimestamp(favorite.createdAt);
+  const updatedAt = normalizeTimestamp(favorite.updatedAt, createdAt);
+  const id = typeof favorite.id === "string" && favorite.id.trim().length > 0
+    ? favorite.id.trim()
+    : nextId("favorite");
+  const note = typeof favorite.note === "string"
+    ? favorite.note
+    : typeof favorite.memory?.note === "string"
+      ? favorite.memory.note
+      : "";
+
+  const normalized = {
+    id,
+    type,
+    title,
+    note,
+    createdAt,
+    updatedAt,
+  };
+
+  const memory = normalizeMemory(favorite.memory, normalized);
+  normalized.memoryId = memory.id;
+  normalized.memory = memory;
+
+  return normalized;
+}
+
+function normalizeState(rawState) {
+  const source = isRecord(rawState) ? rawState : {};
+  const favorites = [];
+  const memories = new Map();
+
+  const rawFavorites = Array.isArray(source.favorites)
+    ? source.favorites
+    : Array.isArray(source)
+      ? source
+      : [];
+
+  for (const favorite of rawFavorites) {
+    const normalized = normalizeFavorite(favorite);
+    favorites.push(normalized);
+    memories.set(normalized.memory.id, clone(normalized.memory));
+  }
+
+  if (Array.isArray(source.memories)) {
+    for (const memory of source.memories) {
+      if (!isRecord(memory)) {
+        continue;
+      }
+
+      const id = typeof memory.id === "string" && memory.id.trim().length > 0
+        ? memory.id.trim()
+        : nextId("memory");
+      if (memories.has(id)) {
+        continue;
+      }
+
+      memories.set(id, {
+        id,
+        title: typeof memory.title === "string" && memory.title.trim().length > 0
+          ? memory.title.trim()
+          : "Recuerdo guardado",
+        note: typeof memory.note === "string" ? memory.note : "",
+        createdAt: normalizeTimestamp(memory.createdAt),
+        source: typeof memory.source === "string" && memory.source.trim().length > 0
+          ? memory.source.trim()
+          : "favorite",
+        favoriteId: typeof memory.favoriteId === "string" ? memory.favoriteId : null,
+        favoriteType: typeof memory.favoriteType === "string" ? memory.favoriteType : null,
+      });
+    }
+  }
+
+  return {
+    favorites,
+    memories: Array.from(memories.values()),
+  };
+}
+
+function readState(namespace = FAVORITES_NAMESPACE) {
+  return normalizeState(readNamespace(namespace));
+}
+
+function writeState(namespace, state) {
+  const normalized = normalizeState(state);
+  return writeNamespace(namespace, normalized);
+}
+
+function findFavoriteIndex(state, favoriteId) {
+  return state.favorites.findIndex((favorite) => favorite.id === favoriteId);
+}
+
+function syncMemoryForFavorite(favorite, memoryInput) {
+  const memory = normalizeMemory(memoryInput, favorite);
+  return {
+    ...favorite,
+    memoryId: memory.id,
+    memory,
+    updatedAt: normalizeTimestamp(favorite.updatedAt, favorite.createdAt),
+  };
+}
+
+function removeFavoriteFromState(state, favoriteId) {
+  const nextFavorites = state.favorites.filter((favorite) => favorite.id !== favoriteId);
+  const nextMemories = state.memories.filter((memory) => memory.favoriteId !== favoriteId);
+
+  return {
+    favorites: nextFavorites,
+    memories: nextMemories,
+  };
+}
+
+function saveState(namespace, state) {
+  return writeState(namespace, state);
+}
+
+export function listFavorites(namespace = FAVORITES_NAMESPACE) {
+  return readState(namespace).favorites.map((favorite) => clone(favorite));
+}
+
+export function listMemories(namespace = FAVORITES_NAMESPACE) {
+  return readState(namespace).memories.map((memory) => clone(memory));
+}
+
+export function listFavoritesWithMemories(namespace = FAVORITES_NAMESPACE) {
+  return listFavorites(namespace).map((favorite) => ({
+    ...favorite,
+    memory: clone(favorite.memory),
+  }));
+}
+
+export function readFavoritesState(namespace = FAVORITES_NAMESPACE) {
+  return readState(namespace);
+}
+
+export function writeFavoritesState(state, namespace = FAVORITES_NAMESPACE) {
+  return saveState(namespace, state);
+}
+
+export function createFavorite(input, namespace = FAVORITES_NAMESPACE) {
+  const state = readState(namespace);
+  const favorite = normalizeFavorite(input);
+  const memory = normalizeMemory(input?.memory, favorite);
+  const nextFavorite = {
+    ...favorite,
+    memoryId: memory.id,
+    memory,
+    updatedAt: normalizeTimestamp(input?.updatedAt, favorite.createdAt),
+  };
+
+  state.favorites.push(nextFavorite);
+  state.memories.push(clone(memory));
+  saveState(namespace, state);
+  return clone(nextFavorite);
+}
+
+export function addFavorite(input, namespace = FAVORITES_NAMESPACE) {
+  return createFavorite(input, namespace);
+}
+
+export function createIntegratedMemory(favoriteId, memoryInput = {}, namespace = FAVORITES_NAMESPACE) {
+  const state = readState(namespace);
+  const index = findFavoriteIndex(state, ensureNonEmptyString(favoriteId, "favorite id"));
+
+  if (index === -1) {
+    throw new RangeError(`favorite not found: ${favoriteId}`);
+  }
+
+  const favorite = state.favorites[index];
+  const nextFavorite = syncMemoryForFavorite(favorite, memoryInput);
+  const nextState = {
+    favorites: state.favorites.slice(),
+    memories: state.memories.filter((memory) => memory.favoriteId !== favorite.id),
+  };
+
+  nextState.favorites[index] = nextFavorite;
+  nextState.memories.push(clone(nextFavorite.memory));
+  saveState(namespace, nextState);
+  return clone(nextFavorite.memory);
+}
+
+export function removeFavorite(favoriteId, namespace = FAVORITES_NAMESPACE) {
+  const id = ensureNonEmptyString(favoriteId, "favorite id");
+  const state = readState(namespace);
+  const nextState = removeFavoriteFromState(state, id);
+
+  if (nextState.favorites.length === state.favorites.length) {
+    return false;
+  }
+
+  saveState(namespace, nextState);
+  return true;
+}
+
+export function toggleFavorite(input, namespace = FAVORITES_NAMESPACE) {
+  const state = readState(namespace);
+  const favoriteId = isRecord(input) ? input.id : input;
+
+  if (typeof favoriteId === "string" && favoriteId.trim().length > 0) {
+    const trimmed = favoriteId.trim();
+    const index = findFavoriteIndex(state, trimmed);
+    if (index !== -1) {
+      const nextState = removeFavoriteFromState(state, trimmed);
+      saveState(namespace, nextState);
+      return { action: "removed", favorite: clone(state.favorites[index]) };
+    }
+  }
+
+  const favorite = createFavorite(isRecord(input) ? input : { title: String(input), type: "place" }, namespace);
+  return { action: "added", favorite };
+}
+
+export function subscribeFavorites(listener, namespace = FAVORITES_NAMESPACE) {
+  return subscribe(namespace, listener);
+}
+
+export function createFavoritesStore(namespace = FAVORITES_NAMESPACE) {
+  return {
+    namespace,
+    read: () => readFavoritesState(namespace),
+    write: (state) => writeFavoritesState(state, namespace),
+    subscribe: (listener) => subscribeFavorites(listener, namespace),
+    listFavorites: () => listFavorites(namespace),
+    listMemories: () => listMemories(namespace),
+    listFavoritesWithMemories: () => listFavoritesWithMemories(namespace),
+    createFavorite: (input) => createFavorite(input, namespace),
+    addFavorite: (input) => addFavorite(input, namespace),
+    createIntegratedMemory: (favoriteId, memoryInput) => createIntegratedMemory(favoriteId, memoryInput, namespace),
+    removeFavorite: (favoriteId) => removeFavorite(favoriteId, namespace),
+    toggleFavorite: (input) => toggleFavorite(input, namespace),
+  };
+}
+
+export const favorites = createFavoritesStore();
+
+export default favorites;
