+}
+
+export function createIntegratedMemory(note, memory = {}) {
+  const normalizedNote = normalizeNoteShape(note);
+  return normalizeIntegratedMemory(normalizedNote, memory);
+}
+
+export function createNote(note) {
+  return normalizeNoteShape(note);
+}
+
+export function addNote(note) {
+  const normalizedNote = normalizeNoteShape(note);
+  const notes = readNotes();
+  const nextNotes = [...notes, normalizedNote];
+  writeNamespace(NOTES_NAMESPACE, nextNotes);
