+  return readState(namespace).favorites.map((favorite) => clone(favorite));
+}
+
+export function listMemories(namespace = FAVORITES_NAMESPACE) {
+  return readState(namespace).memories.map((memory) => clone(memory));
+}
+
+export function listFavoritesWithMemories(namespace = FAVORITES_NAMESPACE) {
+  return listFavorites(namespace).map((favorite) => ({
+    ...favorite,
+    memory: clone(favorite.memory),
+  }));
+}
+
+export function readFavoritesState(namespace = FAVORITES_NAMESPACE) {
+  return readState(namespace);
+}
+
+export function writeFavoritesState(state, namespace = FAVORITES_NAMESPACE) {
+  return saveState(namespace, state);
+}
+
+export function createFavorite(input, namespace = FAVORITES_NAMESPACE) {
+  const state = readState(namespace);
+  const favorite = normalizeFavorite(input);
+  const memory = normalizeMemory(input?.memory, favorite);
+  const nextFavorite = {
+    ...favorite,
+    memoryId: memory.id,
+    memory,
+    updatedAt: normalizeTimestamp(input?.updatedAt, favorite.createdAt),
+  };
+
+  state.favorites.push(nextFavorite);
+  state.memories.push(clone(memory));
+  saveState(namespace, state);
+  return clone(nextFavorite);
+}
+
+export function addFavorite(input, namespace = FAVORITES_NAMESPACE) {
+  return createFavorite(input, namespace);
+}
+
+export function createIntegratedMemory(favoriteId, memoryInput = {}, namespace = FAVORITES_NAMESPACE) {
+  const state = readState(namespace);
+  const index = findFavoriteIndex(state, ensureNonEmptyString(favoriteId, "favorite id"));
+
+  if (index === -1) {
+    throw new RangeError(`favorite not found: ${favoriteId}`);
+  }
+
+  const favorite = state.favorites[index];
+  const nextFavorite = syncMemoryForFavorite(favorite, memoryInput);
+  const nextState = {
+    favorites: state.favorites.slice(),
+    memories: state.memories.filter((memory) => memory.favoriteId !== favorite.id),
+  };
+
+  nextState.favorites[index] = nextFavorite;
+  nextState.memories.push(clone(nextFavorite.memory));
+  saveState(namespace, nextState);
+  return clone(nextFavorite.memory);
+}
+
+export function removeFavorite(favoriteId, namespace = FAVORITES_NAMESPACE) {
+  const id = ensureNonEmptyString(favoriteId, "favorite id");
+  const state = readState(namespace);
+  const nextState = removeFavoriteFromState(state, id);
+
+  if (nextState.favorites.length === state.favorites.length) {
+    return false;
+  }
+
+  saveState(namespace, nextState);
+  return true;
+}
+
+export function toggleFavorite(input, namespace = FAVORITES_NAMESPACE) {
+  const state = readState(namespace);
+  const favoriteId = isRecord(input) ? input.id : input;
+
+  if (typeof favoriteId === "string" && favoriteId.trim().length > 0) {
+    const trimmed = favoriteId.trim();
+    const index = findFavoriteIndex(state, trimmed);
+    if (index !== -1) {
+      const nextState = removeFavoriteFromState(state, trimmed);
+      saveState(namespace, nextState);
+      return { action: "removed", favorite: clone(state.favorites[index]) };
+    }
+  }
+
+  const favorite = createFavorite(isRecord(input) ? input : { title: String(input), type: "place" }, namespace);
+  return { action: "added", favorite };
+}
+
+export function subscribeFavorites(listener, namespace = FAVORITES_NAMESPACE) {
+  return subscribe(namespace, listener);
+}
+
+export function createFavoritesStore(namespace = FAVORITES_NAMESPACE) {
+  return {
+    namespace,
+    read: () => readFavoritesState(namespace),
+    write: (state) => writeFavoritesState(state, namespace),
+    subscribe: (listener) => subscribeFavorites(listener, namespace),
+    listFavorites: () => listFavorites(namespace),
+    listMemories: () => listMemories(namespace),
+    listFavoritesWithMemories: () => listFavoritesWithMemories(namespace),
+    createFavorite: (input) => createFavorite(input, namespace),
+    addFavorite: (input) => addFavorite(input, namespace),
+    createIntegratedMemory: (favoriteId, memoryInput) => createIntegratedMemory(favoriteId, memoryInput, namespace),
+    removeFavorite: (favoriteId) => removeFavorite(favoriteId, namespace),
+    toggleFavorite: (input) => toggleFavorite(input, namespace),
+  };
+}
+
+export const favorites = createFavoritesStore();
+
+export default favorites;
