+  const itemsSource = Array.isArray(input.items) ? input.items : defaultPackingItems;
+  const items = itemsSource
+    .map((item, index) => normalizeItem(item, index))
+    .filter(Boolean);
+
+  return {
+    version: 1,
+    title: normalizeText(input.title, "Checklist de equipaje"),
+    description: normalizeText(
+      input.description,
+      "Agregar, completar, filtrar y ver el progreso total del equipaje.",
+    ),
+    filter: normalizeFilter(input.filter),
+    draft: normalizeText(input.draft),
+    items,
+  };
+}
+
+export function getPackingProgress(stateOrItems = {}) {
+  const state = Array.isArray(stateOrItems)
+    ? { items: stateOrItems }
+    : stateOrItems;
+  const items = Array.isArray(state.items) ? state.items : [];
