+  });
+
+  controls.appendChild(form);
+  container.appendChild(controls);
+
+  const visibleItems = filterPackingItems(state.items, state.filter);
+  const list = doc.createElement("ul");
+  list.className = "packing-checklist__list";
+
+  if (visibleItems.length === 0) {
+    list.appendChild(createEmptyState(doc));
+  } else {
+    for (const item of visibleItems) {
+      list.appendChild(createPackingItemNode(doc, item, (id, packed) => {
+        store.toggleItem(id, packed);
+      }));
+    }
+  }
+
+  container.appendChild(list);
+}
+
+export function createPackingChecklist(options = {}) {
