+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+function findFirst(node, predicate) {
+  if (predicate(node)) {
+    return node;
+  }
+
+  for (const child of node.childNodes ?? []) {
+    const match = findFirst(child, predicate);
+    if (match) {
+      return match;
+    }
+  }
+
+  return null;
+}
+
+function findAll(node, predicate, result = []) {
+  if (predicate(node)) {
+    result.push(node);
+  }
+
+  for (const child of node.childNodes ?? []) {
+    findAll(child, predicate, result);
+  }
+
+  return result;
+}
+
+let cleanup = () => {};
+
+async function loadPackingModule() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.document = new FakeDocument();
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.document;
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${moduleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("packing state helpers normalize items and compute progress", async () => {
+  const { addPackingItem, filterPackingItems, getPackingProgress, normalizePackingState } =
+    await loadPackingModule();
+
+  const state = normalizePackingState({
+    title: "Checklist de equipaje",
+    filter: "packed",
+    items: [{ id: "one", label: "Botella", packed: false }],
+  });
+
+  assert.equal(state.title, "Checklist de equipaje");
+  assert.equal(state.filter, "packed");
+  assert.deepEqual(getPackingProgress(state), { total: 1, packed: 0, pending: 1, percent: 0 });
+
+  const nextState = addPackingItem(state, { label: "Cargador", category: "Tecnología" });
+  assert.equal(nextState.items.length, 2);
+  assert.deepEqual(filterPackingItems(nextState, "pending").map((item) => item.label), [
+    "Botella",
+    "Cargador",
+  ]);
+});
+
+test("createPackingChecklist supports creation, completion, filtering, and total progress", async () => {
+  const { createPackingChecklist, packingNamespace } = await loadPackingModule();
+
+  const checklist = createPackingChecklist({
+    initialState: {
+      items: [
+        { id: "documents", label: "Documentos", packed: false, category: "Imprescindibles" },
+        { id: "charger", label: "Cargador", packed: true, category: "Tecnología" },
+      ],
+    },
+  });
+
+  assert.equal(checklist.className, "shell-layout");
+  assert.equal(globalThis.localStorage.getItem(packingNamespace), JSON.stringify({
+    version: 1,
+    title: "Checklist de equipaje",
+    description: "Agregar, completar, filtrar y ver el progreso total del equipaje.",
+    filter: "all",
+    draft: "",
+    items: [
+      { id: "documents", label: "Documentos", packed: false, category: "Imprescindibles" },
+      { id: "charger", label: "Cargador", packed: true, category: "Tecnología" },
+    ],
+  }));
+
+  const toolbar = findFirst(checklist, (node) => node.getAttribute?.("role") === "toolbar");
+  assert.ok(toolbar);
+
+  const progressSummary = findFirst(checklist, (node) => node.className === "packing-checklist__progress-summary");
+  assert.ok(progressSummary);
+  assert.equal(progressSummary.textContent, "1 de 2 listos (50%)");
+
+  const addForm = findFirst(checklist, (node) => node.tagName === "FORM");
+  assert.ok(addForm);
+
+  const inputs = findAll(addForm, (node) => node.tagName === "INPUT");
+  assert.equal(inputs.length, 2);
+  const [labelInput, categoryInput] = inputs;
+  labelInput.value = "Traje de baño";
+  categoryInput.value = "Ropa";
+
+  addForm.dispatchEvent({
+    type: "submit",
+    preventDefault() {},
+  });
+
+  assert.match(globalThis.localStorage.getItem(packingNamespace), /Traje de baño/);
+
+  const list = findFirst(checklist, (node) => node.className === "packing-checklist__list");
+  assert.ok(list);
+  assert.equal(findAll(list, (node) => node.className === "packing-checklist__item").length, 3);
+
+  const pendingFilter = findAll(toolbar, (node) => node.tagName === "BUTTON").find((button) => button.textContent === "Pendientes");
+  assert.ok(pendingFilter);
+  pendingFilter.dispatchEvent({ type: "click" });
+
+  const pendingList = findFirst(checklist, (node) => node.className === "packing-checklist__list");
+  assert.ok(pendingList);
+  const pendingItems = findAll(pendingList, (node) => node.className === "packing-checklist__item");
+  assert.equal(pendingItems.length, 2);
+  assert.deepEqual(pendingItems.map((item) => item.dataset.itemId), ["documents", "charger"]);
+
+  const documentCheckbox = findFirst(checklist, (node) => node.tagName === "INPUT" && node.parentNode?.textContent?.includes("Documentos"));
+  assert.ok(documentCheckbox);
+  documentCheckbox.checked = true;
+  documentCheckbox.dispatchEvent({ type: "change" });
+
+  const updatedProgress = findFirst(checklist, (node) => node.className === "packing-checklist__progress-summary");
+  assert.ok(updatedProgress);
+  assert.equal(updatedProgress.textContent, "2 de 3 listos (67%)");
+});

