+import { createShellLayout } from "../shell/layout.mjs";
+import { readNamespace, subscribe, writeNamespace } from "../shell/storage.mjs";
+
+export const packingNamespace = "organization-packing";
+export const packingFilters = Object.freeze(["all", "packed", "pending"]);
+export const packingStates = Object.freeze({
+  all: "all",
+  packed: "packed",
+  pending: "pending",
+});
+
+export const defaultPackingItems = Object.freeze([
+  { id: "documents", label: "Documentos", packed: false, category: "Imprescindibles" },
+  { id: "tickets", label: "Pasajes", packed: false, category: "Imprescindibles" },
+  { id: "clothes", label: "Ropa", packed: false, category: "Equipaje" },
+  { id: "toiletries", label: "Aseo personal", packed: false, category: "Equipaje" },
+  { id: "medication", label: "Medicamentos", packed: false, category: "Salud" },
+]);
+
+let generatedIdCounter = 0;
+
+function getDocument() {
+  const doc = globalThis.document;
+  if (!doc || typeof doc.createElement !== "function") {
+    throw new Error("document is required to build packing checklists");
+  }
+  return doc;
+}
+
+function isPlainObject(value) {
+  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
+}
+
+function normalizeText(value, fallback = "") {
+  if (typeof value === "string") {
+    const trimmed = value.trim();
+    return trimmed.length > 0 ? trimmed : fallback;
+  }
+
+  if (typeof value === "number" && Number.isFinite(value)) {
+    return String(value);
+  }
+
+  return fallback;
+}
+
+function normalizeId(value, fallbackPrefix = "item") {
+  const text = normalizeText(value);
+  if (text) {
+    return text;
+  }
+
+  generatedIdCounter += 1;
+  return `${fallbackPrefix}-${generatedIdCounter}`;
+}
+
+function normalizeFilter(value) {
+  return packingFilters.includes(value) ? value : packingStates.all;
+}
+
+function normalizeItem(item, index = 0) {
+  if (!isPlainObject(item)) {
+    return null;
+  }
+
+  const label = normalizeText(item.label);
+  if (!label) {
+    return null;
+  }
+
+  return {
+    id: normalizeId(item.id, `packing-item-${index + 1}`),
+    label,
+    packed: Boolean(item.packed),
+    category: normalizeText(item.category),
+  };
+}
+
+export function normalizePackingState(value = {}) {
+  const input = isPlainObject(value) ? value : {};
+  const itemsSource = Array.isArray(input.items) ? input.items : defaultPackingItems;
+  const items = itemsSource
+    .map((item, index) => normalizeItem(item, index))
+    .filter(Boolean);
+
+  return {
+    version: 1,
+    title: normalizeText(input.title, "Checklist de equipaje"),
+    description: normalizeText(
+      input.description,
+      "Agregar, completar, filtrar y ver el progreso total del equipaje.",
+    ),
+    filter: normalizeFilter(input.filter),
+    draft: normalizeText(input.draft),
+    items,
+  };
+}
+
+export function getPackingProgress(stateOrItems = {}) {
+  const state = Array.isArray(stateOrItems)
+    ? { items: stateOrItems }
+    : stateOrItems;
+  const items = Array.isArray(state.items) ? state.items : [];
+  const total = items.length;
+  const packed = items.filter((item) => Boolean(item?.packed)).length;
+  const pending = total - packed;
+  const percent = total === 0 ? 0 : Math.round((packed / total) * 100);
+
+  return {
+    total,
+    packed,
+    pending,
+    percent,
+  };
+}
+
+export function filterPackingItems(stateOrItems = {}, filter = packingStates.all) {
+  const state = Array.isArray(stateOrItems)
+    ? { items: stateOrItems }
+    : stateOrItems;
+  const normalizedFilter = normalizeFilter(filter);
+  const items = Array.isArray(state.items) ? state.items : [];
+
+  if (normalizedFilter === packingStates.packed) {
+    return items.filter((item) => Boolean(item?.packed));
+  }
+
+  if (normalizedFilter === packingStates.pending) {
+    return items.filter((item) => !Boolean(item?.packed));
+  }
+
+  return items.slice();
+}
+
+export function addPackingItem(state, item) {
+  const normalizedState = normalizePackingState(state);
+  const nextItem = normalizeItem(item, normalizedState.items.length);
+
+  if (!nextItem) {
+    return normalizedState;
+  }
+
+  return {
+    ...normalizedState,
+    items: [...normalizedState.items, nextItem],
+  };
+}
+
+export function togglePackingItem(state, id, packed) {
+  const normalizedState = normalizePackingState(state);
+  const nextItems = normalizedState.items.map((item) => {
+    if (item.id !== id) {
+      return item;
+    }
+
+    return {
+      ...item,
+      packed: typeof packed === "boolean" ? packed : !item.packed,
+    };
+  });
+
+  return {
+    ...normalizedState,
+    items: nextItems,
+  };
+}
+
+export function setPackingFilter(state, filter) {
+  const normalizedState = normalizePackingState(state);
+  return {
+    ...normalizedState,
+    filter: normalizeFilter(filter),
+  };
+}
+
+export function createPackingStore(namespace = packingNamespace, initialState = {}) {
+  const storedState = readNamespace(namespace);
+  let state = normalizePackingState(storedState ?? initialState);
+
+  function persist(nextState) {
+    state = normalizePackingState(nextState);
+    writeNamespace(namespace, state);
+    return state;
+  }
+
+  return {
+    namespace,
+    getState() {
+      return state;
+    },
+    setState(nextState) {
+      return persist(nextState);
+    },
+    addItem(item) {
+      return persist(addPackingItem(state, item));
+    },
+    toggleItem(id, packed) {
+      return persist(togglePackingItem(state, id, packed));
+    },
+    setFilter(filter) {
+      return persist(setPackingFilter(state, filter));
+    },
+    replaceItems(items) {
+      return persist({
+        ...state,
+        items: Array.isArray(items)
+          ? items.map((item, index) => normalizeItem(item, index)).filter(Boolean)
+          : state.items,
+      });
+    },
+  };
+}
+
+function createClassList(...classes) {
+  return classes.filter(Boolean).join(" ");
+}
+
+function clearNode(node) {
+  if (typeof node.replaceChildren === "function") {
+    node.replaceChildren();
+    return;
+  }
+
+  if ("textContent" in node) {
+    node.textContent = "";
+    return;
+  }
+
+  node.childNodes = [];
+}
+
+function findFirstByClass(node, className) {
+  if (!node || typeof node !== "object") {
+    return null;
+  }
+
+  if (typeof node.className === "string" && node.className.split(/\s+/).includes(className)) {
+    return node;
+  }
+
+  for (const child of node.childNodes ?? []) {
+    const match = findFirstByClass(child, className);
+    if (match) {
+      return match;
+    }
+  }
+
+  return null;
+}
+
+function appendValue(target, value) {
+  if (value === null || value === undefined || value === false) {
+    return;
+  }
+
+  const doc = getDocument();
+
+  if (Array.isArray(value)) {
+    for (const item of value) {
+      appendValue(target, item);
+    }
+    return;
+  }
+
+  if (typeof value === "string" || typeof value === "number") {
+    target.appendChild(doc.createTextNode(String(value)));
+    return;
+  }
+
+  target.appendChild(value);
+}
+
+function createButton(doc, label, { pressed = false, onClick, value } = {}) {
+  const button = doc.createElement("button");
+  button.type = "button";
+  button.textContent = label;
+  button.className = createClassList("packing-checklist__filter", pressed && "is-active");
+  button.setAttribute("aria-pressed", pressed ? "true" : "false");
+  if (value !== undefined) {
+    if (!("dataset" in button)) {
+      button.dataset = {};
+    }
+    button.dataset.value = value;
+  }
+  if (typeof onClick === "function") {
+    button.addEventListener("click", onClick);
+  }
+  return button;
+}
+
+function createProgressNode(doc, progress) {
+  const panel = doc.createElement("section");
+  panel.className = "packing-checklist__progress";
+  panel.setAttribute("aria-label", "Progreso total");
+
+  const heading = doc.createElement("h2");
+  heading.textContent = "Progreso total";
+  panel.appendChild(heading);
+
+  const summary = doc.createElement("p");
+  summary.className = "packing-checklist__progress-summary";
+  summary.textContent = `${progress.packed} de ${progress.total} listos (${progress.percent}%)`;
+  panel.appendChild(summary);
+
+  const bar = doc.createElement("div");
+  bar.className = "packing-checklist__progress-bar";
+  bar.setAttribute("role", "progressbar");
+  bar.setAttribute("aria-valuemin", "0");
+  bar.setAttribute("aria-valuemax", "100");
+  bar.setAttribute("aria-valuenow", String(progress.percent));
+  bar.setAttribute("aria-label", "Progreso total del equipaje");
+
+  const fill = doc.createElement("span");
+  fill.className = "packing-checklist__progress-bar-fill";
+  fill.style.width = `${progress.percent}%`;
+  bar.appendChild(fill);
+
+  panel.appendChild(bar);
+  return panel;
+}
+
+function createEmptyState(doc) {
+  const empty = doc.createElement("p");
+  empty.className = "packing-checklist__empty";
+  empty.textContent = "No hay elementos para mostrar.";
+  return empty;
+}
+
+function createPackingItemNode(doc, item, onToggle) {
+  const row = doc.createElement("li");
+  row.className = createClassList("packing-checklist__item", item.packed && "is-packed");
+  if (!("dataset" in row)) {
+    row.dataset = {};
+  }
+  row.dataset.itemId = item.id;
+
+  const label = doc.createElement("label");
+  label.className = "packing-checklist__item-label";
+
+  const checkbox = doc.createElement("input");
+  checkbox.type = "checkbox";
+  checkbox.checked = Boolean(item.packed);
+  checkbox.addEventListener("change", () => onToggle(item.id, checkbox.checked));
+  label.appendChild(checkbox);
+
+  const text = doc.createElement("span");
+  text.className = "packing-checklist__item-text";
+  text.textContent = item.label;
+  label.appendChild(text);
+
+  row.appendChild(label);
+
+  if (item.category) {
+    const category = doc.createElement("span");
+    category.className = "packing-checklist__item-category";
+    category.textContent = item.category;
+    row.appendChild(category);
+  }
+
+  return row;
+}
+
+function createFormField(doc, labelText, inputName, placeholder) {
+  const wrapper = doc.createElement("label");
+  wrapper.className = "packing-checklist__field";
+
+  const label = doc.createElement("span");
+  label.textContent = labelText;
+  wrapper.appendChild(label);
+
+  const input = doc.createElement("input");
+  input.name = inputName;
+  input.placeholder = placeholder;
+  wrapper.appendChild(input);
+
+  return { wrapper, input };
+}
+
+function renderChecklistContent(container, state, store) {
+  const doc = getDocument();
+  clearNode(container);
+
+  const progress = getPackingProgress(state.items);
+  container.appendChild(createProgressNode(doc, progress));
+
+  const controls = doc.createElement("div");
+  controls.className = "packing-checklist__controls";
+
+  const filters = doc.createElement("div");
+  filters.className = "packing-checklist__filters";
+  filters.setAttribute("role", "toolbar");
+  filters.setAttribute("aria-label", "Filtros del equipaje");
+
+  const filterLabels = {
+    all: "Todos",
+    packed: "Completos",
+    pending: "Pendientes",
+  };
+
+  for (const filter of packingFilters) {
+    filters.appendChild(
+      createButton(doc, filterLabels[filter], {
+        pressed: state.filter === filter,
+        value: filter,
+        onClick: () => store.setFilter(filter),
+      }),
+    );
+  }
+
+  controls.appendChild(filters);
+
+  const form = doc.createElement("form");
+  form.className = "packing-checklist__form";
+
+  const { wrapper: itemField, input: itemInput } = createFormField(
+    doc,
+    "Nuevo elemento",
+    "label",
+    "Por ejemplo: Cargador",
+  );
+  const { wrapper: categoryField, input: categoryInput } = createFormField(
+    doc,
+    "Categoría",
+    "category",
+    "Por ejemplo: Tecnología",
+  );
+
+  const submit = doc.createElement("button");
+  submit.type = "submit";
+  submit.textContent = "Agregar";
+
+  form.appendChild(itemField);
+  form.appendChild(categoryField);
+  form.appendChild(submit);
+
+  form.addEventListener("submit", (event) => {
+    event.preventDefault();
+    const label = itemInput.value;
+    const category = categoryInput.value;
+    if (!normalizeText(label)) {
+      return;
+    }
+
+    store.addItem({
+      label,
+      category,
+      packed: false,
+    });
+
+    itemInput.value = "";
+    categoryInput.value = "";
+    itemInput.focus?.();
+  });
+
+  controls.appendChild(form);
+  container.appendChild(controls);
+
+  const visibleItems = filterPackingItems(state.items, state.filter);
+  const list = doc.createElement("ul");
+  list.className = "packing-checklist__list";
+
+  if (visibleItems.length === 0) {
+    list.appendChild(createEmptyState(doc));
+  } else {
+    for (const item of visibleItems) {
+      list.appendChild(createPackingItemNode(doc, item, (id, packed) => {
+        store.toggleItem(id, packed);
+      }));
+    }
+  }
+
+  container.appendChild(list);
+}
+
+export function createPackingChecklist(options = {}) {
+  const doc = getDocument();
+  const store = createPackingStore(options.namespace ?? packingNamespace, options.initialState ?? {});
+  const state = store.getState();
+
+  if (readNamespace(store.namespace) === null && globalThis.localStorage) {
+    writeNamespace(store.namespace, state);
+  }
+
+  const layout = createShellLayout({
+    title: normalizeText(options.title, state.title),
+    description: normalizeText(options.description, state.description),
+    label: "Checklist de equipaje",
+    children: [],
+    aside: {
+      label: "Resumen del equipaje",
+      content: [createProgressNode(doc, getPackingProgress(state.items))],
+    },
+  });
+
+  const main = findFirstByClass(layout, "shell-layout__main") ?? layout.childNodes?.[1]?.childNodes?.[0];
+  if (!main) {
+    throw new Error("packing checklist main area is unavailable");
+  }
+
+  const content = doc.createElement("div");
+  content.className = "packing-checklist";
+  main.appendChild(content);
+
+  const rerender = () => {
+    const currentState = normalizePackingState(store.getState());
+    renderChecklistContent(content, currentState, store);
+
+    const progress = getPackingProgress(currentState.items);
+    const aside = findFirstByClass(layout, "shell-layout__aside");
+    if (aside) {
+      clearNode(aside);
+      aside.appendChild(createProgressNode(doc, progress));
+    }
+  };
+
+  const unsubscribe = subscribe(store.namespace, () => {
+    rerender();
+  });
+
+  rerender();
+
+  Object.defineProperties(layout, {
+    store: {
+      value: store,
+      enumerable: false,
+    },
+    destroy: {
+      value: () => unsubscribe(),
+      enumerable: false,
+    },
+  });
+
+  return layout;
+}
+
+export const createPackingOrganization = createPackingChecklist;
+export const createOrganizationPacking = createPackingChecklist;
+export const createPackingApp = createPackingChecklist;
