+      title: "Desayuno en la terraza",
+      summary: "La familia empezó el día sin apuro.",
+    },
+  });
+
+  const favorite = memoriesModule.createFavorite({
+    type: "place",
+    title: "Playa",
+    note: "Un recuerdo luminoso",
+  });
+
