+  assert.equal(featured[0].noteId, note.id);
+  assert.equal(featured[0].summary, "La familia empezó el día sin apuro.");
+  assert.equal(featured[1].source, "favorite");
+  assert.equal(featured[1].favoriteId, favorite.id);
+  assert.equal(featured[1].note, "Un recuerdo luminoso");
+});
+
+test("subscribeFeaturedMemories emite el conjunto combinado al cambiar notas o favoritos", async () => {
+  const { memoriesModule } = await loadModules();
+  const observed = [];
+
+  const unsubscribe = memoriesModule.subscribeFeaturedMemories((memories) => {
+    observed.push(memories);
+  });
+
+  assert.equal(observed.length, 1);
+  assert.deepEqual(observed[0], []);
+
+  memoriesModule.addNote({
+    text: "Anotar una pausa",
