+    localStorage: Object.getOwnPropertyDescriptor(globalThis, "localStorage"),
+    window: Object.getOwnPropertyDescriptor(globalThis, "window"),
+    crypto: Object.getOwnPropertyDescriptor(globalThis, "crypto"),
