+  const api = {
+    namespace,
+    get state() {
+      return snapshot();
+    },
+    get items() {
+      return getItems();
+    },
+    get filter() {
+      return state.filter;
+    },
+    get progress() {
+      return getProgress();
+    },
+    get visibleItems() {
+      return getVisibleItems();
+    },
+    addItem,
+    toggleItem,
+    completeItem,
+    setFilter,
+    removeItem,
+    clearPacked,
+    subscribe,
+    destroy,
+    snapshot,
+    getItems,
+    getVisibleItems,
+    getProgress,
+    allItems() {
+      return getItems();
+    },
+  };
+
+  return api;
+}
+
+function createButton(doc, label, onClick, active = false) {
