+  assert.equal(afterAdd.items.length, 1);
+  assert.equal(afterAdd.items[0].label, "Campera");
+  assert.equal(afterAdd.items[0].packed, false);
+  assert.deepEqual(afterAdd.progress, {
+    total: 1,
+    packed: 0,
