+    return update((current) => ({
+      ...current,
+      items: [
+        ...current.items,
+        {
+          id: nextItemId(),
+          label: normalizedLabel,
+          packed: false,
+        },
+      ],
+    }));
+  }
+
+  function toggleItem(id) {
+    if (typeof id !== "string" || id.length === 0) {
+      throw new TypeError("id must be a non-empty string");
+    }
+
+    return update((current) => ({
+      ...current,
+      items: current.items.map((item) => (item.id === id ? { ...item, packed: !item.packed } : item)),
+    }));
+  }
+
+  function completeItem(id) {
+    if (typeof id !== "string" || id.length === 0) {
+      throw new TypeError("id must be a non-empty string");
+    }
+
+    return update((current) => ({
+      ...current,
+      items: current.items.map((item) => (item.id === id ? { ...item, packed: true } : item)),
+    }));
+  }
+
+  function setFilter(filter) {
+    return update((current) => ({
+      ...current,
+      filter: normalizeFilter(filter),
+    }));
+  }
+
+  function removeItem(id) {
+    if (typeof id !== "string" || id.length === 0) {
+      throw new TypeError("id must be a non-empty string");
+    }
+
+    return update((current) => ({
+      ...current,
+      items: current.items.filter((item) => item.id !== id),
+    }));
+  }
+
+  function clearPacked() {
+    return update((current) => ({
+      ...current,
+      items: current.items.filter((item) => !item.packed),
+    }));
+  }
+
+  function subscribe(listener) {
+    if (typeof listener !== "function") {
+      throw new TypeError("listener must be a function");
+    }
+    listeners.add(listener);
+    return () => {
+      listeners.delete(listener);
+    };
+  }
+
+  function destroy() {
+    listeners.clear();
+    unsubscribeNamespace();
+  }
+
+  const api = {
+    namespace,
+    get state() {
+      return snapshot();
+    },
+    get items() {
+      return getItems();
+    },
+    get filter() {
+      return state.filter;
+    },
+    get progress() {
+      return getProgress();
+    },
+    get visibleItems() {
+      return getVisibleItems();
+    },
+    addItem,
+    toggleItem,
+    completeItem,
+    setFilter,
+    removeItem,
+    clearPacked,
+    subscribe,
+    destroy,
+    snapshot,
+    getItems,
+    getVisibleItems,
+    getProgress,
+    allItems() {
+      return getItems();
+    },
+  };
+
+  return api;
+}
+
+function createButton(doc, label, onClick, active = false) {
+  const button = doc.createElement("button");
+  button.type = "button";
+  button.textContent = label;
+  button.className = active ? "packing-checklist__filter packing-checklist__filter--active" : "packing-checklist__filter";
