+function nextItemId() {
+  itemIdCounter += 1;
+  const randomPart = typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
+    ? crypto.randomUUID()
+    : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
+  return `packing-item-${itemIdCounter}-${randomPart}`;
