+
+function normalizeFilter(filter) {
+  if (filter === PACKING_FILTERS.all || filter === PACKING_FILTERS.pending || filter === PACKING_FILTERS.packed) {
+    return filter;
+  }
+  return PACKING_FILTERS.all;
