@@ -0,0 +1,175 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+const moduleUrl = new URL("./packing.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+let cleanup = () => {};
+
+async function loadPackingModule() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${moduleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("createPackingChecklist normalizes an integrated organization and tracks progress", async () => {
+  const { createPackingChecklist, createIntegratedOrganization, getPackingProgress, getPackingItems } = await loadPackingModule();
+
+  const organization = createIntegratedOrganization({
+    title: "Family trip",
+    sections: [
+      {
+        title: "Documents",
+        items: [{ label: "Pasaportes", completed: true }, "Tickets"],
+      },
+      "Electronics",
+    ],
+  });
+
+  assert.equal(organization.title, "Family trip");
+  assert.equal(organization.sections.length, 2);
+  assert.equal(organization.sections[0].items.length, 2);
+
+  const checklist = createPackingChecklist({
+    title: "Checklist de equipaje",
+    organization,
+    items: [
+      { label: "Pasaportes", completed: true },
+      { label: "Tickets" },
+      { label: "Cargadores" },
+    ],
+  });
+
+  assert.equal(checklist.title, "Checklist de equipaje");
+  assert.equal(checklist.organization.title, "Family trip");
+  assert.deepEqual(getPackingProgress(checklist), {
+    total: 3,
+    completed: 1,
+    remaining: 2,
+    percent: 33,
+  });
+  assert.equal(getPackingItems(checklist).length, 3);
+});
+
+test("addPackingItem, completePackingItem, togglePackingItem and setPackingFilter update the checklist", async () => {
+  const {
+    addPackingItem,
+    completePackingItem,
+    createPackingChecklist,
+    getPackingItems,
+    getPackingProgress,
+    setPackingFilter,
+    togglePackingItem,
+    PACKING_FILTERS,
+  } = await loadPackingModule();
+
+  const base = createPackingChecklist({
+    items: [
+      { id: "passport", label: "Pasaportes" },
+      { id: "charger", label: "Cargadores", completed: true },
+    ],
+  });
+
+  const withBag = addPackingItem(base, { id: "bag", label: "Mochila" });
+  assert.equal(withBag.items.length, 3);
+  assert.equal(withBag.items[2].label, "Mochila");
+
+  const completed = completePackingItem(withBag, "bag");
+  assert.equal(completed.items.find((item) => item.id === "bag").completed, true);
+
+  const toggled = togglePackingItem(completed, "charger");
+  assert.equal(toggled.items.find((item) => item.id === "charger").completed, false);
+
+  const pendingOnly = setPackingFilter(toggled, PACKING_FILTERS.pending);
+  assert.equal(pendingOnly.filter, PACKING_FILTERS.pending);
+  assert.deepEqual(
+    getPackingItems(pendingOnly),
+    pendingOnly.items.filter((item) => !item.completed),
+  );
+
+  assert.deepEqual(getPackingProgress(pendingOnly), {
+    total: 3,
+    completed: 1,
+    remaining: 2,
+    percent: 33,
+  });
+});
+
+test("savePackingChecklist, loadPackingChecklist and subscribePackingChecklist use the shell storage seam", async () => {
+  const { loadPackingChecklist, savePackingChecklist, subscribePackingChecklist, createPackingChecklist, PACKING_NAMESPACE } = await loadPackingModule();
+
+  const observed = [];
+  const unsubscribe = subscribePackingChecklist((state) => {
+    observed.push(state);
+  });
+
+  const saved = savePackingChecklist(
+    createPackingChecklist({
+      title: "Trip packing",
+      items: [{ label: "Medicines" }],
+    }),
+  );
+
+  assert.equal(globalThis.localStorage.getItem(PACKING_NAMESPACE), JSON.stringify(saved));
+  assert.deepEqual(loadPackingChecklist(), saved);
+  assert.deepEqual(observed, [saved]);
+
+  globalThis.localStorage.setItem(PACKING_NAMESPACE, JSON.stringify({ title: "From storage", items: [] }));
+  globalThis.window.dispatchStorageEvent(PACKING_NAMESPACE);
+
+  assert.equal(observed.at(-1).title, "From storage");
+
+  unsubscribe();
+  savePackingChecklist(createPackingChecklist({ title: "After unsubscribe" }));
+  assert.equal(observed.at(-1).title, "From storage");
+});

diff --git a/public/itinerary-stops/stops.mjs b/public/itinerary-stops/stops.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..6445872e25d815ccef1b8dc543861095cb03d98c
--- /dev/null
+++ b/public/itinerary-stops/stops.mjs
@@ -0,0 +1,246 @@
+import { readNamespace, writeNamespace } from "../shell/storage.mjs";
+
+const STORAGE_NAMESPACE = "itinerary-stops";
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function toText(value) {
+  return typeof value === "string" ? value : "";
+}
+
+function toOrder(value) {
+  return Number.isInteger(value) && value > 0 ? value : null;
+}
+
+function stopComparator(left, right) {
+  if (left.order !== right.order) {
+    return left.order - right.order;
+  }
+
+  return left.id.localeCompare(right.id);
+}
+
+function normalizeStop(stop, fallbackOrder) {
+  if (!isRecord(stop) || typeof stop.id !== "string" || stop.id.length === 0) {
+    return null;
+  }
+
+  const order = toOrder(stop.order) ?? fallbackOrder;
+  if (!Number.isInteger(order) || order <= 0) {
+    return null;
+  }
+
+  return {
+    id: stop.id,
+    name: toText(stop.name),
+    startDate: toText(stop.startDate),
+    endDate: toText(stop.endDate),
+    description: toText(stop.description),
+    order,
+  };
+}
+
+function readStopsState() {
+  const stored = readNamespace(STORAGE_NAMESPACE);
+  if (!Array.isArray(stored)) {
+    return [];
+  }
+
+  const normalized = [];
+  for (let index = 0; index < stored.length; index += 1) {
+    const stop = normalizeStop(stored[index], index + 1);
+    if (stop) {
+      normalized.push(stop);
+    }
+  }
+
+  normalized.sort(stopComparator);
+
+  return normalized.map((stop, index) => ({
+    ...stop,
+    order: index + 1,
+  }));
+}
+
+function persistStops(stops) {
+  return writeNamespace(STORAGE_NAMESPACE, stops);
+}
+
+function createId() {
+  const crypto = globalThis.crypto;
+  if (crypto && typeof crypto.randomUUID === "function") {
+    return crypto.randomUUID();
+  }
+
+  return `stop-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+function resolveId(input) {
+  if (typeof input === "string") {
+    return input;
+  }
+
+  if (isRecord(input) && typeof input.id === "string") {
+    return input.id;
+  }
+
+  throw new TypeError("id must be a string");
+}
+
+function resolveOrderIndex(stops, desiredOrder) {
+  if (!Number.isInteger(desiredOrder) || desiredOrder <= 0) {
+    return stops.length;
+  }
+
+  return Math.min(desiredOrder - 1, stops.length);
+}
+
+function rebuildOrders(stops) {
+  return stops.map((stop, index) => ({
+    ...stop,
+    order: index + 1,
+  }));
+}
+
+function pickMutableFields(patch) {
+  const next = {};
+
+  if (Object.hasOwn(patch, "name")) {
+    next.name = toText(patch.name);
+  }
+  if (Object.hasOwn(patch, "startDate")) {
+    next.startDate = toText(patch.startDate);
+  }
+  if (Object.hasOwn(patch, "endDate")) {
+    next.endDate = toText(patch.endDate);
+  }
+  if (Object.hasOwn(patch, "description")) {
+    next.description = toText(patch.description);
+  }
+
+  return next;
+}
+
+export function listStops() {
+  return readStopsState();
+}
+
+export function createStop(stop = {}) {
+  if (!isRecord(stop)) {
+    throw new TypeError("stop must be an object");
+  }
+
+  const stops = readStopsState();
+  const insertAt = resolveOrderIndex(stops, toOrder(stop.order));
+  const created = normalizeStop(
+    {
+      id: createId(),
+      name: toText(stop.name),
+      startDate: toText(stop.startDate),
+      endDate: toText(stop.endDate),
+      description: toText(stop.description),
+      order: insertAt + 1,
+    },
+    insertAt + 1,
+  );
+
+  const nextStops = [...stops];
+  nextStops.splice(insertAt, 0, created);
+
+  const persisted = rebuildOrders(nextStops);
+  persistStops(persisted);
+
+  return persisted[persisted.length - 1] === created
+    ? persisted[insertAt]
+    : persisted.find((candidate) => candidate.id === created.id) ?? created;
+}
+
+export function updateStop(idOrStop, patch = {}) {
+  const id = resolveId(idOrStop);
+  if (!isRecord(patch)) {
+    throw new TypeError("patch must be an object");
+  }
+
+  const stops = readStopsState();
+  const index = stops.findIndex((stop) => stop.id === id);
+  if (index === -1) {
+    throw new RangeError(`Stop not found: ${id}`);
+  }
+
+  const current = stops[index];
+  const remaining = stops.filter((_, stopIndex) => stopIndex !== index);
+  const nextStop = {
+    ...current,
+    ...pickMutableFields(patch),
+  };
+
+  const desiredOrder = Object.hasOwn(patch, "order") ? toOrder(patch.order) : current.order;
+  const insertAt = resolveOrderIndex(remaining, desiredOrder);
+  remaining.splice(insertAt, 0, nextStop);
+
+  const persisted = rebuildOrders(remaining);
+  persistStops(persisted);
+
+  return persisted.find((stop) => stop.id === id) ?? nextStop;
+}
+
+export function removeStop(idOrStop) {
+  const id = resolveId(idOrStop);
+
+  const stops = readStopsState();
+  const index = stops.findIndex((stop) => stop.id === id);
+  if (index === -1) {
+    throw new RangeError(`Stop not found: ${id}`);
+  }
+
+  const [removed] = stops.splice(index, 1);
+  persistStops(rebuildOrders(stops));
+
+  return removed;
+}
+
+export function reorderStops(nextOrder = []) {
+  if (!Array.isArray(nextOrder)) {
+    throw new TypeError("nextOrder must be an array");
+  }
+
+  const stops = readStopsState();
+  if (nextOrder.length === 0) {
+    const persisted = rebuildOrders(stops);
+    persistStops(persisted);
+    return persisted;
+  }
+
+  const byId = new Map(stops.map((stop) => [stop.id, stop]));
+  const ordered = [];
+  const seen = new Set();
+
+  for (const item of nextOrder) {
+    const id = resolveId(item);
+    if (seen.has(id)) {
+      throw new RangeError(`Duplicate stop id in reorder list: ${id}`);
+    }
+
+    const stop = byId.get(id);
+    if (!stop) {
+      throw new RangeError(`Stop not found: ${id}`);
+    }
+
+    seen.add(id);
+    ordered.push(stop);
+  }
+
+  for (const stop of stops) {
+    if (!seen.has(stop.id)) {
+      ordered.push(stop);
+    }
+  }
+
+  const persisted = rebuildOrders(ordered);
+  persistStops(persisted);
+
+  return persisted;
+}
+
