+import { readNamespace, subscribe as subscribeNamespace, writeNamespace } from "../shell/storage.mjs";
+
+export const PACKING_NAMESPACE = "organization-packing";
+
+export const PACKING_FILTERS = Object.freeze({
+  all: "all",
+  completed: "completed",
+  pending: "pending",
+});
+
+const DEFAULT_TITLE = "Checklist de equipaje";
+
+let itemSequence = 0;
+
+function nextItemId(prefix = "packing-item") {
+  itemSequence += 1;
+  return `${prefix}-${itemSequence}`;
+}
+
+function isPlainObject(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function toBoolean(value) {
+  return value === true;
+}
+
+function normalizeText(value, fallback = "") {
+  if (typeof value === "string") {
+    const trimmed = value.trim();
+    return trimmed.length > 0 ? trimmed : fallback;
+  }
+
+  return fallback;
+}
+
+function normalizeFilter(filter) {
+  if (filter === PACKING_FILTERS.completed || filter === PACKING_FILTERS.pending) {
+    return filter;
+  }
+
+  return PACKING_FILTERS.all;
+}
+
+function resolveItemLabel(item, fallbackIndex) {
+  if (typeof item === "string") {
+    return normalizeText(item, `Elemento ${fallbackIndex + 1}`);
+  }
+
+  if (isPlainObject(item)) {
+    return normalizeText(item.label ?? item.name ?? item.title, `Elemento ${fallbackIndex + 1}`);
+  }
+
+  return `Elemento ${fallbackIndex + 1}`;
+}
+
+function resolveItemCategory(item) {
+  if (!isPlainObject(item)) {
+    return null;
+  }
+
+  const category = normalizeText(item.category ?? item.group ?? item.section, "");
+  return category.length > 0 ? category : null;
+}
+
+function normalizePackingItem(item, fallbackIndex) {
+  const label = resolveItemLabel(item, fallbackIndex);
+  const completed = isPlainObject(item) ? toBoolean(item.completed ?? item.done ?? item.checked) : false;
+  const category = resolveItemCategory(item);
+  const note = isPlainObject(item) ? normalizeText(item.note ?? item.description, "") : "";
+  const id = isPlainObject(item) && typeof item.id === "string" && item.id.trim().length > 0
+    ? item.id.trim()
+    : nextItemId();
+
+  return {
+    id,
+    label,
+    completed,
+    category,
+    note: note.length > 0 ? note : null,
+  };
+}
+
+function normalizeOrganization(organization) {
+  if (!isPlainObject(organization)) {
+    return null;
+  }
+
+  const title = normalizeText(organization.title ?? organization.name, "");
+  const sections = Array.isArray(organization.sections)
+    ? organization.sections
+        .map((section, index) => {
+          if (typeof section === "string") {
+            return {
+              id: nextItemId("packing-section"),
+              title: normalizeText(section, `Seccion ${index + 1}`),
+              items: [],
+            };
+          }
+
+          if (!isPlainObject(section)) {
+            return null;
+          }
+
+          const sectionTitle = normalizeText(section.title ?? section.name, `Seccion ${index + 1}`);
+          const sectionItems = Array.isArray(section.items) ? section.items : [];
+
+          return {
+            id: typeof section.id === "string" && section.id.trim().length > 0 ? section.id.trim() : nextItemId("packing-section"),
+            title: sectionTitle,
+            items: sectionItems.map((entry, itemIndex) => normalizePackingItem(entry, itemIndex)),
+          };
+        })
+        .filter(Boolean)
+    : [];
+
+  return {
+    id: typeof organization.id === "string" && organization.id.trim().length > 0 ? organization.id.trim() : nextItemId("packing-organization"),
+    title: title.length > 0 ? title : DEFAULT_TITLE,
+    sections,
+  };
+}
+
+function normalizeState(state) {
+  if (!isPlainObject(state)) {
+    return createPackingChecklist();
+  }
+
+  const items = Array.isArray(state.items) ? state.items.map((item, index) => normalizePackingItem(item, index)) : [];
+
+  return {
+    title: normalizeText(state.title, DEFAULT_TITLE),
+    filter: normalizeFilter(state.filter),
+    items,
+    organization: normalizeOrganization(state.organization),
+  };
+}
+
+export function createIntegratedOrganization(input = {}) {
+  const organization = normalizeOrganization(input);
+  return organization ?? {
+    id: nextItemId("packing-organization"),
+    title: DEFAULT_TITLE,
+    sections: [],
+  };
+}
+
+export function createPackingChecklist(input = {}) {
+  const organizationSource =
+    input.organization ??
+    (Array.isArray(input.sections)
+      ? {
+          title: input.organizationTitle ?? input.title,
+          sections: input.sections,
+        }
+      : null);
+  const organization = organizationSource ? createIntegratedOrganization(organizationSource) : null;
+  const items = Array.isArray(input.items) ? input.items.map((item, index) => normalizePackingItem(item, index)) : [];
+
+  return {
+    title: normalizeText(input.title, DEFAULT_TITLE),
+    filter: normalizeFilter(input.filter),
+    items,
+    organization,
+  };
+}
+
+export function addPackingItem(state, item) {
+  const current = normalizeState(state);
+  return {
+    ...current,
+    items: [...current.items, normalizePackingItem(item, current.items.length)],
+  };
+}
+
+export function completePackingItem(state, itemId, completed = true) {
+  const current = normalizeState(state);
+
+  return {
+    ...current,
+    items: current.items.map((item) =>
+      item.id === itemId
+        ? {
+            ...item,
+            completed: completed === true,
+          }
+        : item,
+    ),
+  };
+}
+
+export function togglePackingItem(state, itemId) {
+  const current = normalizeState(state);
+
+  return {
+    ...current,
+    items: current.items.map((item) =>
+      item.id === itemId
+        ? {
+            ...item,
+            completed: !item.completed,
+          }
+        : item,
+    ),
+  };
+}
+
+export function setPackingFilter(state, filter) {
+  const current = normalizeState(state);
+  return {
+    ...current,
+    filter: normalizeFilter(filter),
+  };
+}
+
+export function getPackingItems(state, filter = null) {
+  const current = normalizeState(state);
+  const appliedFilter = normalizeFilter(filter ?? current.filter);
+
+  if (appliedFilter === PACKING_FILTERS.completed) {
+    return current.items.filter((item) => item.completed);
+  }
+
+  if (appliedFilter === PACKING_FILTERS.pending) {
+    return current.items.filter((item) => !item.completed);
+  }
+
+  return current.items.slice();
+}
+
+export function getPackingProgress(state) {
+  const current = normalizeState(state);
+  const total = current.items.length;
+  const completed = current.items.filter((item) => item.completed).length;
+  const remaining = total - completed;
+  const percent = total === 0 ? 0 : Math.round((completed / total) * 100);
+
+  return {
+    total,
+    completed,
+    remaining,
+    percent,
+  };
+}
+
+export function loadPackingChecklist() {
+  const stored = readNamespace(PACKING_NAMESPACE);
+  return normalizeState(stored);
+}
+
+export function savePackingChecklist(state) {
+  const normalized = normalizeState(state);
+  writeNamespace(PACKING_NAMESPACE, normalized);
+  return normalized;
+}
+
+export function subscribePackingChecklist(listener) {
+  return subscribeNamespace(PACKING_NAMESPACE, () => {
+    listener(loadPackingChecklist());
+  });
+}
+
+export function createPackingOrganization(input = {}) {
+  return createIntegratedOrganization(input);
+}
+
+export function createPackingState(input = {}) {
+  return createPackingChecklist(input);
+}
+
+export default {
+  PACKING_FILTERS,
+  PACKING_NAMESPACE,
+  addPackingItem,
+  completePackingItem,
+  createIntegratedOrganization,
+  createPackingChecklist,
+  createPackingOrganization,
+  createPackingState,
+  getPackingItems,
+  getPackingProgress,
+  loadPackingChecklist,
+  savePackingChecklist,
+  setPackingFilter,
+  subscribePackingChecklist,
+  togglePackingItem,
+};
