+test("addPackingItem, completePackingItem, togglePackingItem and setPackingFilter update the checklist", async () => {
+  const {
+    addPackingItem,
+    completePackingItem,
+    createPackingChecklist,
+    getPackingItems,
+    getPackingProgress,
+    setPackingFilter,
+    togglePackingItem,
+    PACKING_FILTERS,
+  } = await loadPackingModule();
