+  assert.equal(withBag.items[2].label, "Mochila");
+
+  const completed = completePackingItem(withBag, "bag");
+  assert.equal(completed.items.find((item) => item.id === "bag").completed, true);
+
+  const toggled = togglePackingItem(completed, "charger");
+  assert.equal(toggled.items.find((item) => item.id === "charger").completed, false);
+
+  const pendingOnly = setPackingFilter(toggled, PACKING_FILTERS.pending);
+  assert.equal(pendingOnly.filter, PACKING_FILTERS.pending);
