+import assert from "node:assert/strict";
+import test from "node:test";
+
+const moduleUrl = new URL("./packing.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+let cleanup = () => {};
+
+async function loadPackingModule() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${moduleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("createPackingChecklist normalizes an integrated organization and tracks progress", async () => {
+  const { createPackingChecklist, createIntegratedOrganization, getPackingProgress, getPackingItems } = await loadPackingModule();
+
+  const organization = createIntegratedOrganization({
+    title: "Family trip",
+    sections: [
+      {
+        title: "Documents",
+        items: [{ label: "Pasaportes", completed: true }, "Tickets"],
+      },
+      "Electronics",
+    ],
+  });
+
+  assert.equal(organization.title, "Family trip");
+  assert.equal(organization.sections.length, 2);
+  assert.equal(organization.sections[0].items.length, 2);
+
+  const checklist = createPackingChecklist({
+    title: "Checklist de equipaje",
+    organization,
+    items: [
+      { label: "Pasaportes", completed: true },
+      { label: "Tickets" },
+      { label: "Cargadores" },
+    ],
+  });
+
+  assert.equal(checklist.title, "Checklist de equipaje");
+  assert.equal(checklist.organization.title, "Family trip");
+  assert.deepEqual(getPackingProgress(checklist), {
+    total: 3,
+    completed: 1,
+    remaining: 2,
+    percent: 33,
+  });
+  assert.equal(getPackingItems(checklist).length, 3);
+});
+
+test("createPackingChecklist supports integrated organization creation from top-level sections", async () => {
+  const { createPackingChecklist } = await loadPackingModule();
+
+  const checklist = createPackingChecklist({
+    title: "Weekend packing",
+    sections: [
+      {
+        title: "Clothes",
+        items: ["Camisas"],
+      },
+    ],
+  });
+
+  assert.equal(checklist.organization.title, "Weekend packing");
+  assert.equal(checklist.organization.sections[0].title, "Clothes");
+  assert.equal(checklist.organization.sections[0].items[0].label, "Camisas");
+});
+
+test("addPackingItem, completePackingItem, togglePackingItem and setPackingFilter update the checklist", async () => {
+  const {
+    addPackingItem,
+    completePackingItem,
+    createPackingChecklist,
+    getPackingItems,
+    getPackingProgress,
+    setPackingFilter,
+    togglePackingItem,
+    PACKING_FILTERS,
+  } = await loadPackingModule();
+
+  const base = createPackingChecklist({
+    items: [
+      { id: "passport", label: "Pasaportes" },
+      { id: "charger", label: "Cargadores", completed: true },
+    ],
+  });
+
+  const withBag = addPackingItem(base, { id: "bag", label: "Mochila" });
+  assert.equal(withBag.items.length, 3);
+  assert.equal(withBag.items[2].label, "Mochila");
+
+  const completed = completePackingItem(withBag, "bag");
+  assert.equal(completed.items.find((item) => item.id === "bag").completed, true);
+
+  const toggled = togglePackingItem(completed, "charger");
+  assert.equal(toggled.items.find((item) => item.id === "charger").completed, false);
+
+  const pendingOnly = setPackingFilter(toggled, PACKING_FILTERS.pending);
+  assert.equal(pendingOnly.filter, PACKING_FILTERS.pending);
+  assert.deepEqual(
+    getPackingItems(pendingOnly),
+    pendingOnly.items.filter((item) => !item.completed),
+  );
+
+  assert.deepEqual(getPackingProgress(pendingOnly), {
+    total: 3,
+    completed: 1,
+    remaining: 2,
+    percent: 33,
+  });
+});
+
+test("savePackingChecklist, loadPackingChecklist and subscribePackingChecklist use the shell storage seam", async () => {
+  const { loadPackingChecklist, savePackingChecklist, subscribePackingChecklist, createPackingChecklist, PACKING_NAMESPACE } = await loadPackingModule();
+
+  const observed = [];
+  const unsubscribe = subscribePackingChecklist((state) => {
+    observed.push(state);
+  });
+
+  const saved = savePackingChecklist(
+    createPackingChecklist({
+      title: "Trip packing",
+      items: [{ label: "Medicines" }],
+    }),
+  );
+
+  assert.equal(globalThis.localStorage.getItem(PACKING_NAMESPACE), JSON.stringify(saved));
+  assert.deepEqual(loadPackingChecklist(), saved);
+  assert.deepEqual(observed, [saved]);
+
+  globalThis.localStorage.setItem(PACKING_NAMESPACE, JSON.stringify({ title: "From storage", items: [] }));
+  globalThis.window.dispatchStorageEvent(PACKING_NAMESPACE);
+
+  assert.equal(observed.at(-1).title, "From storage");
+
+  unsubscribe();
+  savePackingChecklist(createPackingChecklist({ title: "After unsubscribe" }));
+  assert.equal(observed.at(-1).title, "From storage");
+});

