diff --git a/public/itinerary-agenda/agenda.mjs b/public/itinerary-agenda/agenda.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..879388c15f51848e510f95f3f4a10a9afc117c53
--- /dev/null
+++ b/public/itinerary-agenda/agenda.mjs
@@ -0,0 +1,206 @@
+import { listStops } from "../itinerary-stops/stops.mjs";
+import { readNamespace, writeNamespace } from "../shell/storage.mjs";
+
+const STORAGE_NAMESPACE = "itinerary-agenda";
+const VALID_STATUSES = new Set(["pending", "completed"]);
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function toText(value) {
+  return typeof value === "string" ? value : "";
+}
+
+function toStatus(value) {
+  return VALID_STATUSES.has(value) ? value : "pending";
+}
+
+function createId() {
+  const crypto = globalThis.crypto;
+  if (crypto && typeof crypto.randomUUID === "function") {
+    return crypto.randomUUID();
+  }
+
+  return `activity-${Date.now()}-${Math.random().toString(16).slice(2)}`;
+}
+
+function resolveId(input) {
+  if (typeof input === "string") {
+    return input;
+  }
+
+  if (isRecord(input) && typeof input.id === "string") {
+    return input.id;
+  }
+
+  throw new TypeError("id must be a string");
+}
+
+function normalizeActivity(activity) {
+  if (!isRecord(activity) || typeof activity.id !== "string" || activity.id.length === 0) {
+    return null;
+  }
+
+  return {
+    id: activity.id,
+    stopId: toText(activity.stopId),
+    day: toText(activity.day),
+    time: toText(activity.time),
+    status: toStatus(activity.status),
+  };
+}
+
+function readActivitiesState() {
+  const stored = readNamespace(STORAGE_NAMESPACE);
+  if (!Array.isArray(stored)) {
+    return [];
+  }
+
+  const normalized = [];
+  for (const activity of stored) {
+    const next = normalizeActivity(activity);
+    if (next) {
+      normalized.push(next);
+    }
+  }
+
+  normalized.sort(activityComparator);
+
+  return normalized;
+}
+
+function persistActivities(activities) {
+  return writeNamespace(STORAGE_NAMESPACE, activities);
+}
+
+function stopOrderMap() {
+  return new Map(listStops().map((stop) => [stop.id, stop.order]));
+}
+
+function compareText(left, right) {
+  if (left === right) {
+    return 0;
+  }
+
+  return left < right ? -1 : 1;
+}
+
+function compareStopOrder(leftStopId, rightStopId, orders) {
+  const leftOrder = orders.get(leftStopId) ?? Number.POSITIVE_INFINITY;
+  const rightOrder = orders.get(rightStopId) ?? Number.POSITIVE_INFINITY;
+
+  if (leftOrder !== rightOrder) {
+    return leftOrder - rightOrder;
+  }
+
+  return 0;
+}
+
+function activityComparator(left, right) {
+  const dayComparison = compareText(left.day, right.day);
+  if (dayComparison !== 0) {
+    return dayComparison;
+  }
+
+  const timeComparison = compareText(left.time, right.time);
+  if (timeComparison !== 0) {
+    return timeComparison;
+  }
+
+  const stopComparison = compareStopOrder(left.stopId, right.stopId, stopOrderMap());
+  if (stopComparison !== 0) {
+    return stopComparison;
+  }
+
+  return left.id.localeCompare(right.id);
+}
+
+function pickMutableFields(patch) {
+  const next = {};
+
+  if (Object.hasOwn(patch, "stopId")) {
+    next.stopId = toText(patch.stopId);
+  }
+
+  if (Object.hasOwn(patch, "day")) {
+    next.day = toText(patch.day);
+  }
+
+  if (Object.hasOwn(patch, "time")) {
+    next.time = toText(patch.time);
+  }
+
+  if (Object.hasOwn(patch, "status")) {
+    next.status = toStatus(patch.status);
+  }
+
+  return next;
+}
+
+export function listActivities() {
+  return readActivitiesState();
+}
+
+export function createActivity(activity = {}) {
+  if (!isRecord(activity)) {
+    throw new TypeError("activity must be an object");
+  }
+
+  const activities = readActivitiesState();
+  const created = normalizeActivity({
+    id: createId(),
+    stopId: toText(activity.stopId),
+    day: toText(activity.day),
+    time: toText(activity.time),
+    status: toStatus(activity.status),
+  });
+
+  const nextActivities = [...activities, created];
+  const persisted = nextActivities.sort(activityComparator);
+  persistActivities(persisted);
+
+  return persisted.find((candidate) => candidate.id === created.id) ?? created;
+}
+
+export function updateActivity(idOrActivity, patch = {}) {
+  const id = resolveId(idOrActivity);
+  if (!isRecord(patch)) {
+    throw new TypeError("patch must be an object");
+  }
+
+  const activities = readActivitiesState();
+  const index = activities.findIndex((activity) => activity.id === id);
+  if (index === -1) {
+    throw new RangeError(`Activity not found: ${id}`);
+  }
+
+  const current = activities[index];
+  const nextActivity = {
+    ...current,
+    ...pickMutableFields(patch),
+  };
+
+  const nextActivities = activities
+    .filter((_, activityIndex) => activityIndex !== index)
+    .concat(nextActivity);
+  const persisted = nextActivities.sort(activityComparator);
+  persistActivities(persisted);
+
+  return persisted.find((activity) => activity.id === id) ?? nextActivity;
+}
+
+export function removeActivity(idOrActivity) {
+  const id = resolveId(idOrActivity);
+
+  const activities = readActivitiesState();
+  const index = activities.findIndex((activity) => activity.id === id);
+  if (index === -1) {
+    throw new RangeError(`Activity not found: ${id}`);
+  }
+
+  const [removed] = activities.splice(index, 1);
+  persistActivities(activities);
+
+  return removed;
+}
diff --git a/public/itinerary-agenda/agenda.test.mjs b/public/itinerary-agenda/agenda.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..a7cd6bf7fcf4bfd2a169b27170da9ca8d355af66
--- /dev/null
+++ b/public/itinerary-agenda/agenda.test.mjs
@@ -0,0 +1,237 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+const agendaModuleUrl = new URL("./agenda.mjs", import.meta.url);
+const stopsModuleUrl = new URL("../itinerary-stops/stops.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+    clear() {
+      store.clear();
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+let cleanup = () => {};
+
+async function loadAgendaModule() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${agendaModuleUrl.href}?t=${Date.now()}`);
+}
+
+async function loadStopsModule() {
+  return import(`${stopsModuleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("createActivity persists the daily agenda with a pending default", async () => {
+  const { createActivity, listActivities } = await loadAgendaModule();
+
+  const activity = createActivity({
+    stopId: "stop-1",
+    day: "2026-09-01",
+    time: "09:00",
+  });
+
+  assert.equal(activity.stopId, "stop-1");
+  assert.equal(activity.day, "2026-09-01");
+  assert.equal(activity.time, "09:00");
+  assert.equal(activity.status, "pending");
+  assert.deepEqual(listActivities(), [activity]);
+});
+
+test("listActivities orders activities by day, time, and stop order from the itinerary", async () => {
+  const { createStop } = await loadStopsModule();
+  const { createActivity, listActivities } = await loadAgendaModule();
+
+  const firstStop = createStop({
+    name: "Madrid",
+    startDate: "2026-09-01",
+    endDate: "2026-09-03",
+    description: "Llegada",
+  });
+  const secondStop = createStop({
+    name: "Barcelona",
+    startDate: "2026-09-04",
+    endDate: "2026-09-06",
+    description: "Costa",
+  });
+
+  const laterCreated = createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-02",
+    time: "11:30",
+    status: "completed",
+  });
+  const earlierCreated = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-02",
+    time: "11:30",
+  });
+
+  assert.deepEqual(
+    listActivities().map(({ stopId, day, time, status }) => ({
+      stopId,
+      day,
+      time,
+      status,
+    })),
+    [
+      {
+        stopId: firstStop.id,
+        day: "2026-09-02",
+        time: "11:30",
+        status: "pending",
+      },
+      {
+        stopId: secondStop.id,
+        day: "2026-09-02",
+        time: "11:30",
+        status: "completed",
+      },
+    ],
+  );
+  assert.equal(earlierCreated.stopId, firstStop.id);
+  assert.equal(laterCreated.stopId, secondStop.id);
+});
+
+test("updateActivity edits fields and can move an activity between stops", async () => {
+  const { createStop } = await loadStopsModule();
+  const { createActivity, updateActivity, listActivities } = await loadAgendaModule();
+
+  const firstStop = createStop({
+    name: "Sevilla",
+    startDate: "2026-10-01",
+    endDate: "2026-10-02",
+    description: "Base",
+  });
+  const secondStop = createStop({
+    name: "Granada",
+    startDate: "2026-10-03",
+    endDate: "2026-10-04",
+    description: "Visita",
+  });
+
+  const created = createActivity({
+    stopId: firstStop.id,
+    day: "2026-10-01",
+    time: "08:00",
+  });
+
+  const updated = updateActivity(created.id, {
+    stopId: secondStop.id,
+    day: "2026-10-03",
+    time: "10:30",
+    status: "completed",
+  });
+
+  assert.equal(updated.stopId, secondStop.id);
+  assert.equal(updated.day, "2026-10-03");
+  assert.equal(updated.time, "10:30");
+  assert.equal(updated.status, "completed");
+  assert.deepEqual(listActivities(), [updated]);
+});
+
+test("removeActivity deletes an activity from the agenda", async () => {
+  const { createActivity, removeActivity, listActivities } = await loadAgendaModule();
+
+  const created = createActivity({
+    stopId: "stop-1",
+    day: "2026-11-01",
+    time: "18:15",
+    status: "completed",
+  });
+
+  const removed = removeActivity(created.id);
+
+  assert.equal(removed.id, created.id);
+  assert.deepEqual(listActivities(), []);
+});
+
+test("listActivities normalizes malformed stored data into the shared activity record shape", async () => {
+  const { listActivities } = await loadAgendaModule();
+
+  globalThis.localStorage.setItem(
+    "itinerary-agenda",
+    JSON.stringify([
+      {
+        id: "b",
+        stopId: "stop-2",
+        day: "2026-12-02",
+        time: "18:00",
+        status: "done",
+      },
+      {
+        id: "a",
+        stopId: "stop-1",
+        day: "2026-12-01",
+        time: 42,
+        status: "completed",
+      },
+    ]),
+  );
+
+  assert.deepEqual(listActivities(), [
+    {
+      id: "a",
+      stopId: "stop-1",
+      day: "2026-12-01",
+      time: "",
+      status: "completed",
+    },
+    {
+      id: "b",
+      stopId: "stop-2",
+      day: "2026-12-02",
+      time: "18:00",
+      status: "pending",
+    },
+  ]);
+});

