function compareStopOrder(leftStopId, rightStopId, orders) {
  const leftOrder = orders.get(leftStopId) ?? Number.POSITIVE_INFINITY;
  const rightOrder = orders.get(rightStopId) ?? Number.POSITIVE_INFINITY;

  if (leftOrder !== rightOrder) {
    return leftOrder - rightOrder;
  }

  return 0;
}

function activityComparator(left, right) {
  const dayComparison = compareText(left.day, right.day);
  if (dayComparison !== 0) {
    return dayComparison;
  }

  const timeComparison = compareText(left.time, right.time);
  if (timeComparison !== 0) {
    return timeComparison;
  }

  const stopComparison = compareStopOrder(left.stopId, right.stopId, stopOrderMap());
  if (stopComparison !== 0) {
    return stopComparison;
  }

  return left.id.localeCompare(right.id);
}

function pickMutableFields(patch) {
  const next = {};

  if (Object.hasOwn(patch, "stopId")) {
    next.stopId = toText(patch.stopId);
  }

  if (Object.hasOwn(patch, "day")) {
    next.day = toText(patch.day);
  }

  if (Object.hasOwn(patch, "time")) {
    next.time = toText(patch.time);
  }

  if (Object.hasOwn(patch, "status")) {
    next.status = toStatus(patch.status);
  }

  return next;
}

