+    startDate: "2026-09-03",
+    endDate: "2026-09-04",
+    description: "Rio y vino",
+  });
+  const thirdStop = createStop({
+    name: "Coimbra",
+    startDate: "2026-09-05",
+    endDate: "2026-09-06",
+    description: "Universidad histórica",
+  });
+
+  const laterStopActivity = createActivity({
+    stopId: secondStop.id,
