+      { id: firstStop.id, activityIds: [earlierStopActivity.id] },
+      { id: secondStop.id, activityIds: [laterStopActivity.id] },
+    ],
+  );
+  assert.deepEqual(
+    itinerary.activities.map(({ id, stopId }) => ({ id, stopId })),
+    [
+      { id: earlierStopActivity.id, stopId: firstStop.id },
+      { id: laterStopActivity.id, stopId: secondStop.id },
+    ],
+  );
+  assert.equal(itinerary.stops[0].order, 1);
+  assert.equal(itinerary.stops[1].order, 2);
