+import { listActivities } from "../itinerary-agenda/agenda.mjs";
+import { listStops } from "../itinerary-stops/stops.mjs";
+import { readNamespace, subscribe, writeNamespace } from "../shell/storage.mjs";
+
+const STORAGE_NAMESPACE = "itinerary-search";
+const VALID_SCOPES = new Set(["all", "stops", "activities"]);
+const VALID_STATUSES = new Set(["all", "pending", "completed"]);
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function toText(value) {
+  return typeof value === "string" ? value.trim() : "";
+}
+
+function toLowerText(value) {
+  return toText(value).toLowerCase();
+}
+
+function toStatus(value) {
+  return VALID_STATUSES.has(value) ? value : "all";
+}
+
+function toScope(value) {
+  return VALID_SCOPES.has(value) ? value : "all";
+}
+
+function defaultSearchState() {
+  return {
+    query: "",
+    scope: "all",
+    stopId: "",
+    day: "",
+    status: "all",
+  };
+}
+
+function normalizeSearchState(value) {
+  if (!isRecord(value)) {
+    return defaultSearchState();
+  }
+
+  return {
+    query: toText(value.query),
+    scope: toScope(value.scope),
+    stopId: toText(value.stopId),
+    day: toText(value.day),
+    status: toStatus(value.status),
+  };
+}
+
+function readSearchStateFromStorage() {
+  return normalizeSearchState(readNamespace(STORAGE_NAMESPACE));
+}
+
+function writeSearchStateToStorage(state) {
+  return writeNamespace(STORAGE_NAMESPACE, state);
+}
+
+function mergeSearchState(baseState, patch) {
+  if (!isRecord(patch)) {
+    return baseState;
+  }
+
+  return normalizeSearchState({
+    query: Object.hasOwn(patch, "query") ? patch.query : baseState.query,
+    scope: Object.hasOwn(patch, "scope") ? patch.scope : baseState.scope,
+    stopId: Object.hasOwn(patch, "stopId") ? patch.stopId : baseState.stopId,
+    day: Object.hasOwn(patch, "day") ? patch.day : baseState.day,
+    status: Object.hasOwn(patch, "status") ? patch.status : baseState.status,
+  });
+}
+
+function searchText(haystack, query) {
+  if (query === "") {
+    return true;
+  }
+
+  return haystack.some((value) => value.includes(query));
+}
+
+function stopMatchesQuery(stop, query) {
+  if (query === "") {
+    return true;
+  }
+
+  const haystack = [
+    stop.name,
+    stop.startDate,
+    stop.endDate,
+    stop.description,
+  ].map(toLowerText);
+
+  return searchText(haystack, query);
+}
+
+function activityMatchesQuery(activity, stop, query) {
+  if (query === "") {
+    return true;
+  }
+
+  const haystack = [
+    activity.stopId,
+    activity.day,
+    activity.time,
+    activity.status,
+    stop.name,
+    stop.startDate,
+    stop.endDate,
+    stop.description,
+  ].map(toLowerText);
+
+  return searchText(haystack, query);
+}
+
+function activityMatchesFilters(activity, filters) {
+  if (filters.stopId && activity.stopId !== filters.stopId) {
+    return false;
+  }
+
+  if (filters.day && activity.day !== filters.day) {
+    return false;
+  }
+
+  if (filters.status !== "all" && activity.status !== filters.status) {
+    return false;
+  }
+
+  return true;
+}
+
+function cloneActivity(activity) {
+  return {
+    id: activity.id,
+    stopId: activity.stopId,
+    day: activity.day,
+    time: activity.time,
+    status: activity.status,
+  };
+}
+
+function cloneStop(stop, activities) {
+  return {
+    id: stop.id,
+    name: stop.name,
+    startDate: stop.startDate,
+    endDate: stop.endDate,
+    description: stop.description,
+    order: stop.order,
+    activities: activities.map(cloneActivity),
+  };
+}
+
+function buildIntegratedItinerary(filters = {}) {
+  const baseState = readSearchStateFromStorage();
+  const state = mergeSearchState(baseState, filters);
+  const normalizedQuery = toLowerText(state.query);
+  const stops = listStops();
+  const activities = listActivities();
+
+  const activitiesByStopId = new Map();
+  for (const activity of activities) {
+    const bucket = activitiesByStopId.get(activity.stopId) ?? [];
+    bucket.push(activity);
+    activitiesByStopId.set(activity.stopId, bucket);
+  }
+
+  const matchedStops = [];
+  const matchedActivities = [];
+
+  for (const stop of stops) {
+    const stopActivities = activitiesByStopId.get(stop.id) ?? [];
+    const activitiesAfterFilter = stopActivities.filter((activity) => activityMatchesFilters(activity, state));
+    const activitiesAfterQuery = activitiesAfterFilter.filter((activity) =>
+      activityMatchesQuery(activity, stop, normalizedQuery),
+    );
+
+    const stopQueryMatch = stopMatchesQuery(stop, normalizedQuery);
+    let includedActivities = [];
+
+    if (state.scope === "stops") {
+      if (!stopQueryMatch) {
+        continue;
+      }
+
+      includedActivities = activitiesAfterFilter;
+    } else if (state.scope === "activities") {
+      includedActivities = activitiesAfterQuery;
+      if (includedActivities.length === 0) {
+        continue;
+      }
+    } else {
+      if (stopQueryMatch) {
+        includedActivities = activitiesAfterFilter;
+      } else {
+        includedActivities = activitiesAfterQuery;
+      }
+
+      if (!stopQueryMatch && includedActivities.length === 0) {
+        continue;
+      }
+    }
+
+    const includedStop = cloneStop(stop, includedActivities);
+    matchedStops.push(includedStop);
+    for (const activity of includedStop.activities) {
+      matchedActivities.push(activity);
+    }
+  }
+
+  return {
+    query: state.query,
+    scope: state.scope,
+    stopId: state.stopId,
+    day: state.day,
+    status: state.status,
+    stops: matchedStops,
+    activities: matchedActivities,
+  };
+}
+
+export function readSearchState() {
+  return readSearchStateFromStorage();
+}
+
+export function updateSearchState(patch = {}) {
+  const nextState = mergeSearchState(readSearchStateFromStorage(), patch);
+  return writeSearchStateToStorage(nextState);
+}
+
+export function subscribeSearchState(listener) {
+  return subscribe(STORAGE_NAMESPACE, listener);
+}
+
+export function searchItinerary(filters = {}) {
+  return buildIntegratedItinerary(filters);
+}
+
+export function createIntegratedItinerary(filters = {}) {
+  return buildIntegratedItinerary(filters);
+}
+
+export function listSearchResults(filters = {}) {
+  return buildIntegratedItinerary(filters).stops;
+}
+
+export function createItinerarySearch(filters = {}) {
+  return buildIntegratedItinerary(filters);
+}
+
+export function listItinerarySearchResults(filters = {}) {
+  return buildIntegratedItinerary(filters).stops;
+}
+
