+import assert from "node:assert/strict";
+import test from "node:test";
+
+const searchModuleUrl = new URL("./search.mjs", import.meta.url);
+const stopsModuleUrl = new URL("../itinerary-stops/stops.mjs", import.meta.url);
+const agendaModuleUrl = new URL("../itinerary-agenda/agenda.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+    clear() {
+      store.clear();
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+let cleanup = () => {};
+
+async function loadSearchModule() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  return import(`${searchModuleUrl.href}?t=${Date.now()}`);
+}
+
+async function loadStopsModule() {
+  return import(`${stopsModuleUrl.href}?t=${Date.now()}`);
+}
+
+async function loadAgendaModule() {
+  return import(`${agendaModuleUrl.href}?t=${Date.now()}`);
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("createIntegratedItinerary keeps stop order while filtering activities", async () => {
+  const { createStop } = await loadStopsModule();
+  const { createActivity } = await loadAgendaModule();
+  const { createIntegratedItinerary } = await loadSearchModule();
+
+  const firstStop = createStop({
+    name: "Lisboa",
+    startDate: "2026-09-01",
+    endDate: "2026-09-02",
+    description: "Puente y miradores",
+  });
+  const secondStop = createStop({
+    name: "Porto",
+    startDate: "2026-09-03",
+    endDate: "2026-09-04",
+    description: "Rio y vino",
+  });
+  const thirdStop = createStop({
+    name: "Coimbra",
+    startDate: "2026-09-05",
+    endDate: "2026-09-06",
+    description: "Universidad histórica",
+  });
+
+  const laterStopActivity = createActivity({
+    stopId: secondStop.id,
+    day: "2026-09-03",
+    time: "18:00",
+    status: "completed",
+  });
+  const earlierStopActivity = createActivity({
+    stopId: firstStop.id,
+    day: "2026-09-03",
+    time: "08:00",
+    status: "completed",
+  });
+  createActivity({
+    stopId: thirdStop.id,
+    day: "2026-09-05",
+    time: "10:00",
+    status: "pending",
+  });
+
+  const itinerary = createIntegratedItinerary({
+    scope: "activities",
+    status: "completed",
+  });
+
+  assert.deepEqual(
+    itinerary.stops.map(({ id, activities }) => ({
+      id,
+      activityIds: activities.map((activity) => activity.id),
+    })),
+    [
+      { id: firstStop.id, activityIds: [earlierStopActivity.id] },
+      { id: secondStop.id, activityIds: [laterStopActivity.id] },
+    ],
+  );
+  assert.deepEqual(
+    itinerary.activities.map(({ id, stopId }) => ({ id, stopId })),
+    [
+      { id: earlierStopActivity.id, stopId: firstStop.id },
+      { id: laterStopActivity.id, stopId: secondStop.id },
+    ],
+  );
+  assert.equal(itinerary.stops[0].order, 1);
+  assert.equal(itinerary.stops[1].order, 2);
+});
+
+test("searchItinerary can match stop text and keep the integrated itinerary shape", async () => {
+  const { createStop } = await loadStopsModule();
+  const { createActivity } = await loadAgendaModule();
+  const { searchItinerary } = await loadSearchModule();
+
+  const stop = createStop({
+    name: "Madrid",
+    startDate: "2026-10-01",
+    endDate: "2026-10-02",
+    description: "Museo del Prado",
+  });
+  createActivity({
+    stopId: stop.id,
+    day: "2026-10-01",
+    time: "09:30",
+    status: "pending",
+  });
+
+  const itinerary = searchItinerary({
+    query: "prado",
+  });
+
+  assert.deepEqual(
+    itinerary.stops,
+    [
+      {
+        id: stop.id,
+        name: "Madrid",
+        startDate: "2026-10-01",
+        endDate: "2026-10-02",
+        description: "Museo del Prado",
+        order: 1,
+        activities: [
+          {
+            id: itinerary.activities[0].id,
+            stopId: stop.id,
+            day: "2026-10-01",
+            time: "09:30",
+            status: "pending",
+          },
+        ],
+      },
+    ],
+  );
+});
+
+test("readSearchState normalizes stored data and updateSearchState persists filters", async () => {
+  const { readSearchState, updateSearchState } = await loadSearchModule();
+
+  globalThis.localStorage.setItem(
+    "itinerary-search",
+    JSON.stringify({
+      query: "  museos  ",
