+    status: "completed",
+  });
+
+  assert.deepEqual(nextState, {
+    query: "rio",
+    scope: "stops",
+    stopId: "stop-2",
+    day: "2026-11-01",
+    status: "completed",
+  });
+  assert.equal(
+    globalThis.localStorage.getItem("itinerary-search"),
+    JSON.stringify(nextState),
+  );
+});
+
+test("subscribeSearchState receives same-tab writes and storage events", async () => {
+  const { subscribeSearchState, updateSearchState } = await loadSearchModule();
+  const observed = [];
+
+  const unsubscribe = subscribeSearchState((value) => {
+    observed.push(value);
+  });
+
+  updateSearchState({ query: "porto" });
+  assert.deepEqual(observed, [
+    {
+      query: "porto",
+      scope: "all",
+      stopId: "",
+      day: "",
+      status: "all",
+    },
+  ]);
+
+  globalThis.localStorage.setItem(
+    "itinerary-search",
+    JSON.stringify({
+      query: "lisboa",
+      scope: "activities",
+      stopId: "stop-1",
+      day: "2026-09-01",
+      status: "pending",
+    }),
+  );
+  globalThis.window.dispatchStorageEvent("itinerary-search");
+
+  assert.deepEqual(observed, [
+    {
+      query: "porto",
+      scope: "all",
+      stopId: "",
+      day: "",
+      status: "all",
+    },
+    {
+      query: "lisboa",
+      scope: "activities",
+      stopId: "stop-1",
+      day: "2026-09-01",
+      status: "pending",
+    },
+  ]);
+
+  unsubscribe();
+  updateSearchState({ query: "sevilla" });
+  assert.equal(observed.length, 2);
+});
+

