+import { listActivities } from "../itinerary-agenda/agenda.mjs";
+import { listStops } from "../itinerary-stops/stops.mjs";
+import { searchItinerary as searchIntegratedItinerary } from "../itinerary-search/search.mjs";
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function todayIsoDate() {
+  return new Date().toISOString().slice(0, 10);
+}
+
+function isUpcomingActivity(activity, today) {
+  return activity.status === "pending" && activity.day >= today;
+}
+
+export function listUpcomingEvents() {
+  const today = todayIsoDate();
+  return listActivities().filter((activity) => isUpcomingActivity(activity, today));
+}
+
+export function searchItinerary(query = {}) {
+  if (typeof query === "string") {
+    return searchIntegratedItinerary({ query });
+  }
+
+  if (isRecord(query)) {
+    return searchIntegratedItinerary(query);
+  }
+
+  return searchIntegratedItinerary({ query: String(query ?? "") });
+}
+
+export { listActivities, listStops };

