+import assert from "node:assert/strict";
+import test from "node:test";
+
+const itineraryModuleUrl = new URL("./index.mjs", import.meta.url);
+const stopsModuleUrl = new URL("../itinerary-stops/stops.mjs", import.meta.url);
+const agendaModuleUrl = new URL("../itinerary-agenda/agenda.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+    clear() {
+      store.clear();
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+function todayIsoDate() {
+  return new Date().toISOString().slice(0, 10);
+}
+
+function shiftIsoDate(isoDate, deltaDays) {
+  const date = new Date(`${isoDate}T00:00:00.000Z`);
+  date.setUTCDate(date.getUTCDate() + deltaDays);
+  return date.toISOString().slice(0, 10);
+}
+
+let cleanup = () => {};
+
+async function loadModules() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  const [stopsModule, agendaModule, itineraryModule] = await Promise.all([
+    import(`${stopsModuleUrl.href}?t=${Date.now()}`),
+    import(`${agendaModuleUrl.href}?t=${Date.now()}`),
+    import(`${itineraryModuleUrl.href}?t=${Date.now()}`),
+  ]);
+
+  return { ...stopsModule, ...agendaModule, ...itineraryModule };
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("listUpcomingEvents exposes the pending agenda in chronological order", async () => {
+  const { createStop, createActivity, listUpcomingEvents } = await loadModules();
+
+  const today = todayIsoDate();
+  const yesterday = shiftIsoDate(today, -1);
+  const tomorrow = shiftIsoDate(today, 1);
+
+  const firstStop = createStop({
+    name: "Madrid",
+    startDate: tomorrow,
+    endDate: tomorrow,
+    description: "Centro",
+  });
+  const secondStop = createStop({
+    name: "Barcelona",
+    startDate: tomorrow,
+    endDate: tomorrow,
+    description: "Costa",
+  });
+
+  const todayEvent = createActivity({
+    stopId: firstStop.id,
+    day: today,
+    time: "09:00",
+  });
+  createActivity({
+    stopId: firstStop.id,
+    day: yesterday,
+    time: "08:00",
+  });
+  const tomorrowEvent = createActivity({
+    stopId: secondStop.id,
+    day: tomorrow,
+    time: "09:00",
+  });
+  createActivity({
+    stopId: secondStop.id,
+    day: tomorrow,
+    time: "10:00",
+    status: "completed",
+  });
+
+  assert.deepEqual(listUpcomingEvents(), [todayEvent, tomorrowEvent]);
+});
+
+test("searchItinerary accepts a string query and returns the integrated itinerary shape", async () => {
+  const { createStop, createActivity, searchItinerary } = await loadModules();
+
+  const stop = createStop({
+    name: "Madrid",
+    startDate: "2026-10-01",
+    endDate: "2026-10-02",
+    description: "Museo del Prado",
+  });
+
+  const activity = createActivity({
+    stopId: stop.id,
+    day: "2026-10-01",
+    time: "09:30",
+  });
+
+  const itinerary = searchItinerary("prado");
+
+  assert.equal(itinerary.query, "prado");
+  assert.deepEqual(itinerary.stops, [
+    {
+      id: stop.id,
+      name: "Madrid",
+      startDate: "2026-10-01",
+      endDate: "2026-10-02",
+      description: "Museo del Prado",
+      order: 1,
+      activities: [activity],
+    },
+  ]);
+  assert.deepEqual(itinerary.activities, [activity]);
+});

