+
+.dashboard-empty {
+  margin: 0;
+  padding: 18px;
+  border-radius: var(--radius-md);
+  background: rgba(31, 90, 87, 0.06);
+  color: var(--muted);
+}
+
+.dashboard-list,
+.search-results__activities,
+.budget-categories,
+.packing-list,
+.memory-grid {
+  list-style: none;
+  padding: 0;
+  margin: 0;
+}
+
+.dashboard-list {
+  display: grid;
+  gap: 12px;
+}
+
+.event-card,
+.search-results__stop,
+.memory-card,
+.organization-card {
+  padding: 16px;
+}
+
+.event-card {
+  display: flex;
+  justify-content: space-between;
+  gap: 16px;
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.8);
+  border: 1px solid rgba(59, 49, 38, 0.08);
+}
+
+.event-card__title,
+.memory-card__title,
+.search-results__title {
+  margin: 0;
+  font-size: 1.04rem;
+}
+
+.event-card__meta,
+.search-results__dates,
+.memory-card__text,
+.organization-card__meta {
+  margin: 8px 0 0;
+  color: var(--muted);
+  line-height: 1.5;
+}
+
+.event-card__badge {
+  align-self: flex-start;
+  padding: 6px 10px;
+  border-radius: 999px;
+  background: var(--accent-soft);
+  color: var(--accent-strong);
+  font-size: 0.8rem;
+  font-weight: 700;
+}
+
+.search-results {
+  display: grid;
+  gap: 12px;
+}
+
+.search-results__stop {
+  border-radius: var(--radius-md);
+  border: 1px solid rgba(59, 49, 38, 0.08);
+  background: rgba(255, 255, 255, 0.8);
+}
+
+.search-results__stop-header {
+  display: flex;
+  justify-content: space-between;
+  gap: 12px;
+  align-items: flex-start;
+}
+
+.search-results__count {
+  flex: 0 0 auto;
+  padding: 7px 10px;
+  border-radius: 999px;
+  background: rgba(31, 90, 87, 0.08);
+  color: var(--accent-strong);
+  font-size: 0.82rem;
+  font-weight: 700;
+}
+
+.search-results__description {
+  margin: 12px 0 0;
+  color: var(--muted);
+}
+
+.search-results__activities {
+  display: grid;
+  gap: 8px;
+  margin-top: 14px;
+}
+
+.search-results__activity {
+  display: grid;
+  grid-template-columns: 1fr auto auto;
+  gap: 10px;
+  padding: 10px 12px;
+  border-radius: var(--radius-sm);
+  background: rgba(31, 90, 87, 0.05);
+  color: var(--text);
+  font-size: 0.92rem;
+}
+
+.memory-grid {
+  display: grid;
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.memory-card {
+  border-radius: var(--radius-md);
+  background: rgba(255, 255, 255, 0.8);
+  border: 1px solid rgba(59, 49, 38, 0.08);
+}
+
+.memory-card__title {
+  margin-top: 0;
+}
+
+.budget-categories,
+.packing-list {
+  display: grid;
+  gap: 10px;
+}
+
+.budget-categories__item,
+.packing-list__item {
+  display: flex;
+  justify-content: space-between;
+  gap: 12px;
+  padding: 12px 14px;
+  border-radius: var(--radius-sm);
+  background: rgba(255, 255, 255, 0.8);
+}
+
+.packing-list__item--done {
+  background: rgba(31, 90, 87, 0.08);
+}
+
+.packing-list__status {
+  min-width: 80px;
+  font-size: 0.82rem;
+  font-weight: 700;
+  color: var(--accent-strong);
+}
+
+.packing-list__label {
+  margin-left: auto;
+}
+
+.organization-card {
+  min-height: 100%;
+}
+
+.organization-card__value {
+  display: block;
+  margin-top: 2px;
+  font-size: clamp(1.6rem, 2.4vw, 2.2rem);
+}
+
+@media (max-width: 1080px) {
+  .dashboard-overview,
+  .memory-grid,
+  .dashboard-grid--itinerary,
+  .dashboard-grid--organization,
+  .dashboard-grid--organization-details {
+    grid-template-columns: repeat(2, minmax(0, 1fr));
+  }
+
+  .dashboard-hero {
+    flex-direction: column;
+  }
+
+  .dashboard-panel__header {
+    align-items: flex-start;
+    flex-direction: column;
+  }
+
+  .dashboard-panel__meta {
+    text-align: left;
+  }
+}
+
+@media (max-width: 720px) {
+  .dashboard-shell {
+    width: min(calc(100% - 20px), var(--max-width));
+    padding-top: 16px;
+  }
+
+  .dashboard-hero,
+  .dashboard-panel {
+    padding: 18px;
+    border-radius: 22px;
+  }
+
+  .dashboard-overview,
+  .memory-grid,
+  .dashboard-grid--itinerary,
+  .dashboard-grid--organization,
+  .dashboard-grid--organization-details {
+    grid-template-columns: 1fr;
+  }
+
+  .dashboard-search__controls {
+    flex-direction: column;
+  }
+
+  .search-results__activity {
+    grid-template-columns: 1fr;
+  }
+}
