@@ -0,0 +1,487 @@
+:root {
+  color-scheme: light;
+  --bg: #f3efe7;
+  --bg-2: #ece5d7;
+  --surface: rgba(255, 252, 246, 0.88);
+  --surface-strong: #fffaf1;
+  --text: #1d1b17;
+  --muted: #6f675d;
+  --border: rgba(59, 49, 38, 0.14);
+  --accent: #1f5a57;
+  --accent-strong: #134340;
+  --accent-soft: rgba(31, 90, 87, 0.12);
+  --shadow: 0 20px 60px rgba(50, 35, 18, 0.12);
+  --radius-xl: 28px;
+  --radius-lg: 20px;
+  --radius-md: 14px;
+  --radius-sm: 10px;
+  --max-width: 1240px;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html {
+  scroll-behavior: smooth;
+}
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  color: var(--text);
+  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+  background:
+    radial-gradient(circle at top left, rgba(31, 90, 87, 0.18), transparent 35%),
+    radial-gradient(circle at top right, rgba(189, 140, 63, 0.16), transparent 30%),
+    linear-gradient(180deg, var(--bg), var(--bg-2));
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background-image: linear-gradient(rgba(255, 255, 255, 0.12) 1px, transparent 1px),
+    linear-gradient(90deg, rgba(255, 255, 255, 0.12) 1px, transparent 1px);
+  background-size: 36px 36px;
+  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.28), transparent 72%);
