+}
+
+.overview-card {
+  padding: 18px;
+}
+
+.overview-card__label,
+.overview-card__value {
+  display: block;
+}
+
+.overview-card__value {
+  font-size: clamp(1.5rem, 2vw, 2rem);
+  line-height: 1;
+  letter-spacing: -0.04em;
+}
+
+.dashboard-panel {
+  margin-top: 18px;
+  padding: 24px;
+}
+
+.dashboard-panel__header {
