+  font: inherit;
+}
+
+button {
+  cursor: pointer;
+}
+
+#dashboard-root {
+  position: relative;
+  z-index: 0;
+}
+
+.dashboard-shell {
+  width: min(calc(100% - 32px), var(--max-width));
