diff --git a/test/e2e/e2e.test.mjs b/test/e2e/e2e.test.mjs
new file mode 100644
index 0000000000000000000000000000000000000000..cd52848fcaff6b5a03a1ef33122c1fb50d0bb187
--- /dev/null
+++ b/test/e2e/e2e.test.mjs
@@ -0,0 +1,181 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+const itineraryModuleUrl = new URL("../../public/itinerary/index.mjs", import.meta.url);
+const memoriesModuleUrl = new URL("../../public/memories/index.mjs", import.meta.url);
+const budgetModuleUrl = new URL("../../public/organization-budget/budget.mjs", import.meta.url);
+const packingModuleUrl = new URL("../../public/organization-packing/packing.mjs", import.meta.url);
+const dashboardModuleUrl = new URL("../../public/dashboard/app.mjs", import.meta.url);
+
+function createFakeStorage() {
+  const store = new Map();
+
+  return {
+    store,
+    getItem(key) {
+      return store.has(key) ? store.get(key) : null;
+    },
+    setItem(key, value) {
+      store.set(key, String(value));
+    },
+    removeItem(key) {
+      store.delete(key);
+    },
+    clear() {
+      store.clear();
+    },
+  };
+}
+
+function createFakeWindow(localStorage) {
+  const listeners = new Map();
+
+  return {
+    localStorage,
+    addEventListener(type, listener) {
+      const set = listeners.get(type) ?? new Set();
+      set.add(listener);
+      listeners.set(type, set);
+    },
+    removeEventListener(type, listener) {
+      listeners.get(type)?.delete(listener);
+    },
+    dispatchStorageEvent(key) {
+      for (const listener of listeners.get("storage") ?? []) {
+        listener({ key, storageArea: localStorage });
+      }
+    },
+  };
+}
+
+function todayIsoDate() {
+  const now = new Date();
+  const year = now.getFullYear();
+  const month = String(now.getMonth() + 1).padStart(2, "0");
+  const day = String(now.getDate()).padStart(2, "0");
+
+  return `${year}-${month}-${day}`;
+}
+
+function shiftIsoDate(isoDate, deltaDays) {
+  const date = new Date(`${isoDate}T00:00:00.000Z`);
+  date.setUTCDate(date.getUTCDate() + deltaDays);
+  return date.toISOString().slice(0, 10);
+}
+
+let cleanup = () => {};
+
+async function loadModules() {
+  const storage = createFakeStorage();
+  const windowStub = createFakeWindow(storage);
+
+  globalThis.localStorage = storage;
+  globalThis.window = windowStub;
+
+  cleanup = () => {
+    delete globalThis.localStorage;
+    delete globalThis.window;
+  };
+
+  const [itineraryModule, memoriesModule, budgetModule, packingModule, dashboardModule] = await Promise.all([
+    import(`${itineraryModuleUrl.href}?t=${Date.now()}`),
+    import(`${memoriesModuleUrl.href}?t=${Date.now()}`),
+    import(`${budgetModuleUrl.href}?t=${Date.now()}`),
+    import(`${packingModuleUrl.href}?t=${Date.now()}`),
+    import(`${dashboardModuleUrl.href}?t=${Date.now()}`),
+  ]);
+
+  return {
+    itineraryModule,
+    memoriesModule,
+    budgetModule,
+    packingModule,
+    dashboardModule,
+    storage,
+  };
+}
+
+test.afterEach(() => {
+  cleanup();
+  cleanup = () => {};
+});
+
+test("dashboard snapshot composes itinerary, memories, and organization locally", async () => {
+  const { itineraryModule, memoriesModule, budgetModule, packingModule, dashboardModule, storage } = await loadModules();
+
+  const today = todayIsoDate();
+  const tomorrow = shiftIsoDate(today, 1);
+
+  const stop = itineraryModule.createStop({
+    name: "Madrid",
+    startDate: tomorrow,
+    endDate: tomorrow,
+    description: "Museo del Prado",
+  });
+
+  const activity = itineraryModule.createActivity({
+    stopId: stop.id,
+    day: tomorrow,
+    time: "09:30",
+  });
+
+  memoriesModule.addNote({
+    text: "Reservar desayuno temprano",
+    dayId: "day-1",
+    integratedMemory: {
+      title: "Desayuno en la terraza",
+      summary: "La familia empezo el dia sin apuro.",
+    },
+  });
+
+  memoriesModule.createFavorite({
+    type: "place",
+    title: "Playa",
+    note: "Un recuerdo luminoso",
+  });
+
+  budgetModule.saveBudgetState({
+    totalBudget: 1200,
+    organization: { name: "Familia integrada" },
+    expenses: [
+      { category: "Transporte", amount: 200 },
+      { category: "Comida", amount: 300 },
+    ],
+  });
+
+  packingModule.savePackingChecklist({
+    title: "Checklist de equipaje",
+    items: [
+      { id: "passport", label: "Pasaportes", completed: true },
+      { id: "charger", label: "Cargadores" },
+      { id: "tickets", label: "Tickets" },
+    ],
+  });
+
+  dashboardModule.writeDashboardState({ query: "prado" });
+  assert.equal(storage.getItem("dashboard-state"), JSON.stringify({ query: "prado" }));
+  assert.deepEqual(dashboardModule.readDashboardState(), { query: "prado" });
+
+  const snapshot = dashboardModule.buildDashboardSnapshot();
+
+  assert.equal(snapshot.query, "prado");
+  assert.equal(snapshot.upcomingEvents.length, 1);
+  assert.equal(snapshot.upcomingEvents[0].stopId, stop.id);
+  assert.equal(snapshot.upcomingEvents[0].stopName, "Madrid");
+  assert.equal(snapshot.searchResults.stops.length, 1);
+  assert.equal(snapshot.searchResults.stops[0].name, "Madrid");
+  assert.deepEqual(snapshot.searchResults.activities, [activity]);
+  assert.equal(snapshot.featuredMemories.length, 2);
+  assert.equal(snapshot.featuredMemories[0].source, "note");
+  assert.equal(snapshot.featuredMemories[1].source, "favorite");
+  assert.equal(snapshot.budgetSummary.available, 700);
+  assert.equal(snapshot.packingProgress.percent, 33);
+
+  const markup = dashboardModule.renderDashboardMarkup(snapshot);
+
+  assert.match(markup, /Dashboard integrado de Viaje en Familia/);
+  assert.match(markup, /value="prado"/);
+  assert.match(markup, /Museo del Prado/);
+  assert.match(markup, /Desayuno en la terraza/);
+  assert.match(markup, /Checklist de equipaje/);
+});

