+import { listUpcomingEvents, searchItinerary } from "../itinerary/index.mjs";
+import { listFeaturedMemories } from "../memories/index.mjs";
+import { getBudgetSummary } from "../organization/index.mjs";
+import { loadBudgetState } from "../organization-budget/budget.mjs";
+import { getPackingItems, getPackingProgress, loadPackingChecklist } from "../organization-packing/packing.mjs";
+import { readNamespace, writeNamespace } from "../shell/storage.mjs";
+
+export const DASHBOARD_NAMESPACE = "dashboard-state";
+
+function isRecord(value) {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+function normalizeText(value) {
+  return typeof value === "string" ? value.trim() : "";
+}
+
+function normalizeDashboardState(value) {
+  if (!isRecord(value)) {
+    return { query: "" };
+  }
+
+  return {
+    query: normalizeText(value.query),
+  };
+}
+
+function escapeHtml(value) {
+  return String(value)
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function formatNumber(value) {
+  return new Intl.NumberFormat("es-AR", {
+    maximumFractionDigits: 2,
+    minimumFractionDigits: 0,
+  }).format(value);
+}
+
+function formatPercent(value) {
+  return `${formatNumber(value)}%`;
+}
+
+function defaultStopLabel(stopId) {
+  return stopId ? `Parada ${stopId}` : "Parada sin nombre";
+}
+
+function createStopLookup(stops) {
+  const lookup = new Map();
+  for (const stop of stops) {
+    lookup.set(stop.id, stop);
+  }
+  return lookup;
+}
+
+function enrichUpcomingEvents(upcomingEvents, stopsById) {
+  return upcomingEvents.map((event) => {
+    const stop = stopsById.get(event.stopId);
+    return {
+      ...event,
+      stopName: stop?.name ?? defaultStopLabel(event.stopId),
+      stopDescription: stop?.description ?? "",
+    };
+  });
+}
+
+export function readDashboardState() {
+  return normalizeDashboardState(readNamespace(DASHBOARD_NAMESPACE));
+}
+
+export function writeDashboardState(patch = {}) {
+  const currentState = readDashboardState();
+  const nextState = normalizeDashboardState({
+    query: Object.hasOwn(patch, "query") ? patch.query : currentState.query,
+  });
+
+  writeNamespace(DASHBOARD_NAMESPACE, nextState);
+  return nextState;
+}
+
+export function buildDashboardSnapshot(state = readDashboardState()) {
+  const dashboardState = normalizeDashboardState(state);
+  const query = dashboardState.query;
+  const catalog = searchItinerary("");
+  const searchResults = searchItinerary(query);
+  const stopsById = createStopLookup(catalog.stops);
+  const upcomingEvents = enrichUpcomingEvents(listUpcomingEvents(), stopsById);
+  const featuredMemories = listFeaturedMemories();
+  const budgetSummary = getBudgetSummary(loadBudgetState());
+  const packingChecklist = loadPackingChecklist();
+  const packingProgress = getPackingProgress(packingChecklist);
+  const packingItems = getPackingItems(packingChecklist);
+
+  return {
+    state: dashboardState,
+    query,
+    catalog,
+    searchResults,
+    upcomingEvents,
+    featuredMemories,
+    budgetSummary,
+    packingChecklist,
+    packingProgress,
+    packingItems,
+  };
+}
+
+function renderEmptyState(message) {
+  return `<p class="dashboard-empty">${escapeHtml(message)}</p>`;
+}
+
+function renderUpcomingEvents(events) {
+  if (events.length === 0) {
+    return renderEmptyState("No hay eventos pendientes para los proximos dias.");
+  }
+
+  return `<ol class="dashboard-list dashboard-list--stacked">${events
+    .map(
+      (event) => `
+        <li class="dashboard-list__item">
+          <article class="event-card">
+            <div>
+              <p class="event-card__date">${escapeHtml(event.day)}</p>
+              <h4 class="event-card__title">${escapeHtml(event.stopName)}</h4>
+              <p class="event-card__meta">${escapeHtml(event.time || "Sin hora")} ${event.stopDescription ? `- ${escapeHtml(event.stopDescription)}` : ""}</p>
+            </div>
+            <span class="event-card__badge">Pendiente</span>
+          </article>
+        </li>`,
+    )
+    .join("")}</ol>`;
+}
+
+function renderSearchResults(searchResults) {
+  if (searchResults.stops.length === 0) {
+    return renderEmptyState("No se encontraron coincidencias en el itinerario.");
+  }
+
+  return `<div class="search-results">${searchResults.stops
+    .map(
+      (stop) => `
+        <article class="search-results__stop">
+          <div class="search-results__stop-header">
+            <div>
+              <p class="search-results__eyebrow">Parada ${stop.order}</p>
+              <h4 class="search-results__title">${escapeHtml(stop.name)}</h4>
+              <p class="search-results__dates">${escapeHtml(stop.startDate)} - ${escapeHtml(stop.endDate)}</p>
+            </div>
+            <span class="search-results__count">${stop.activities.length} actividades</span>
+          </div>
+          <p class="search-results__description">${escapeHtml(stop.description || "Sin descripcion")}</p>
+          <ul class="search-results__activities">
+            ${stop.activities
+              .map(
+                (activity) => `
+                  <li class="search-results__activity">
+                    <span>${escapeHtml(activity.day)}</span>
+                    <span>${escapeHtml(activity.time || "Sin hora")}</span>
+                    <span>${escapeHtml(activity.status)}</span>
+                  </li>`,
+              )
+              .join("")}
+          </ul>
+        </article>`,
+    )
+    .join("")}</div>`;
+}
+
+function renderFeaturedMemories(memories) {
+  if (memories.length === 0) {
+    return renderEmptyState("Los recuerdos destacados apareceran cuando haya notas o favoritos integrados.");
+  }
+
+  return `<div class="memory-grid">${memories
+    .map(
+      (memory) => `
+        <article class="memory-card">
+          <p class="memory-card__source">${escapeHtml(memory.source)}</p>
+          <h4 class="memory-card__title">${escapeHtml(memory.title || "Recuerdo")}</h4>
+          <p class="memory-card__text">${escapeHtml(memory.summary || memory.note || "Sin descripcion")}</p>
+        </article>`,
+    )
+    .join("")}</div>`;
+}
+
+function renderBudgetCategories(categories) {
+  if (categories.length === 0) {
+    return renderEmptyState("No hay gastos cargados.");
+  }
+
+  return `<ul class="budget-categories">${categories
+    .map(
+      (category) => `
+        <li class="budget-categories__item">
+          <span>${escapeHtml(category.category)}</span>
+          <strong>${escapeHtml(formatNumber(category.amount))}</strong>
+        </li>`,
+    )
+    .join("")}</ul>`;
+}
+
+function renderPackingItems(items) {
+  if (items.length === 0) {
+    return renderEmptyState("No hay elementos de equipaje cargados.");
+  }
+
+  return `<ul class="packing-list">${items
+    .map(
+      (item) => `
+        <li class="packing-list__item${item.completed ? " packing-list__item--done" : ""}">
+          <span class="packing-list__status">${item.completed ? "Listo" : "Pendiente"}</span>
+          <span class="packing-list__label">${escapeHtml(item.label)}</span>
+        </li>`,
+    )
+    .join("")}</ul>`;
+}
+
+export function renderDashboardMarkup(snapshot = buildDashboardSnapshot()) {
+  const title = "Dashboard integrado de Viaje en Familia";
+  const searchResultsCount = snapshot.searchResults.stops.length;
+  const itineraryActivityCount = snapshot.searchResults.activities.length;
+  const totalStops = snapshot.catalog.stops.length;
+  const availableBudget = snapshot.budgetSummary.available;
+  const packingPercent = snapshot.packingProgress.percent;
+
+  return `
+    <div class="dashboard-shell">
+      <header class="dashboard-hero">
+        <div class="dashboard-hero__copy">
+          <p class="dashboard-hero__eyebrow">Viaje en Familia</p>
+          <h1 class="dashboard-hero__title">${escapeHtml(title)}</h1>
+          <p class="dashboard-hero__summary">Itinerario, organizacion y recuerdos conviven en una sola vista local y persistente.</p>
+        </div>
+        <div class="dashboard-hero__badge">
+          <span>Persistencia local</span>
+          <strong>${escapeHtml(DASHBOARD_NAMESPACE)}</strong>
+        </div>
+      </header>
+
+      <section class="dashboard-overview" aria-label="Resumen general">
+        <article class="overview-card">
+          <span class="overview-card__label">Paradas totales</span>
+          <strong class="overview-card__value">${escapeHtml(totalStops)}</strong>
+        </article>
+        <article class="overview-card">
+          <span class="overview-card__label">Eventos proximos</span>
+          <strong class="overview-card__value">${escapeHtml(snapshot.upcomingEvents.length)}</strong>
+        </article>
+        <article class="overview-card">
+          <span class="overview-card__label">Recuerdos destacados</span>
+          <strong class="overview-card__value">${escapeHtml(snapshot.featuredMemories.length)}</strong>
+        </article>
+        <article class="overview-card">
+          <span class="overview-card__label">Presupuesto disponible</span>
+          <strong class="overview-card__value">${escapeHtml(formatNumber(availableBudget))}</strong>
+        </article>
+        <article class="overview-card">
+          <span class="overview-card__label">Equipaje listo</span>
+          <strong class="overview-card__value">${escapeHtml(formatPercent(packingPercent))}</strong>
+        </article>
+      </section>
+
+      <section class="dashboard-panel dashboard-panel--itinerary" aria-labelledby="itinerary-heading">
+        <header class="dashboard-panel__header">
+          <div>
+            <p class="dashboard-panel__eyebrow">Itinerario</p>
